-- Night availability is controlled by the separate night_config.lua file.
local nightConfig = {[1]=true, [2]=true, [3]=true, [4]=false, [5]=false, [6]=false}
do
  local ok, cfg = pcall(require, "night_config")
  if ok and type(cfg) == "table" then
    for i = 1, 6 do
      if type(cfg[i]) == "boolean" then nightConfig[i] = cfg[i] end
    end
  end
end
local function isNightAvailable(n)
  return n >= 1 and n <= 6 and nightConfig[n] == true
end
local function nextAvailableNight(n)
  for i = n + 1, 6 do
    if isNightAvailable(i) then return i end
  end
  return nil
end
local function nearestAvailableNight(n)
  if isNightAvailable(n) then return n end
  for d = 1, 6 do
    if isNightAvailable(n - d) then return n - d end
    if isNightAvailable(n + d) then return n + d end
  end
  return 1
end
