local curLang = "ru" -- русский по умолчанию

local function LT(key)
  local d = LANGS[curLang]
  local v = d and d[key]
  if v == nil then v = LANGS.ru[key] end
  return v
end

local function L(key, ...)
  local s = LT(key)
  if s == nil then return key end
  if select("#", ...) > 0 then return string.format(s, ...) end
  return s
end

local function callList(n)
  local d = LANGS[curLang]
  if d and d.calls and d.calls[n] then return d.calls[n] end
  return LANGS.ru.calls[n]
end

---------------------------------------------------------------- шрифт и текст
-- Текст рисуется поверх канвы в родном разрешении экрана, поэтому кириллица читается чётко.
local fontCache = {}
-- Встроенный шрифт (подмножество DejaVu Sans Condensed Bold: латиница + кириллица), чтобы не нужен был отдельный файл
local FONT_B64 = ""
local function getFont(px)
  px = max(6, floor(px + .5))
  local f = fontCache[px]
  if not f then
    if not fontCache.data then
      local ok, dec = pcall(love.data.decode, "string", "base64", FONT_B64)
      if ok and dec then fontCache.data = love.filesystem.newFileData(dec, "font.ttf") end
    end
    if fontCache.data then
      local ok, ras = pcall(love.font.newTrueTypeRasterizer, fontCache.data, px)
      if ok and ras then
        local ok2, nf = pcall(lg.newFont, ras)
        if ok2 then f = nf end
      end
    end
    if not f then
      if love.filesystem.getInfo("font.ttf") then f = lg.newFont("font.ttf", px) else f = lg.newFont(px) end
    end
    f:setFilter("linear", "linear")
    fontCache[px] = f
  end
  return f
end

local TQ, TN = {}, 0
-- T(текст, x, y, ширина, цвет, размер, альфа, выравнивание) — координаты виртуальные
local function T(str, x, y, w, col, sz, a, al)
  TN = TN + 1
  local q = TQ[TN]
  if not q then q = {}; TQ[TN] = q end
  q.s, q.x, q.y, q.w = str, x, y, w or W
  q.c, q.sz, q.a, q.al = col or WHITE, sz or 7, a, al or "center"
end

local function flushText()
  for i = 1, TN do
    local q = TQ[i]
    lg.setFont(getFont(q.sz * scale))
    local c = q.c
    lg.setColor(c[1], c[2], c[3], q.a or c[4] or 1)
    lg.printf(q.s, floor(ox + q.x * scale), floor(oy + q.y * scale), floor(q.w * scale), q.al)
  end
  TN = 0
end

---------------------------------------------------------------- помощники
local function hex(s)
  return {tonumber(s:sub(1, 2), 16) / 255, tonumber(s:sub(3, 4), 16) / 255, tonumber(s:sub(5, 6), 16) / 255}
end

local function R(x, y, w, h, c, a)
  lg.setColor(c[1], c[2], c[3], a or c[4] or 1)
  lg.rectangle("fill", floor(x), floor(y), floor(w), floor(h))
end

local function hit(px, py, x, y, w, h)
  return px >= x and px <= x + w and py >= y and py <= y + h
end

local function btn(x, y, w, h, label, bg, tc, sz)
  R(x, y, w, h, bg or {.07, .07, .09}, .92)
  lg.setColor(.7, .7, .7)
  lg.rectangle("line", x + .5, y + .5, w - 1, h - 1)
  T(label, x, y + (h - 8) / 2, w, tc or WHITE, sz or 7)
end

local function static(n, a)
  for _ = 1, n do
    lg.setColor(1, 1, 1, a * rnd())
    lg.rectangle("fill", rnd(0, W - 1), rnd(0, H - 1), rnd(1, 3), 1)
  end
end

local function scanlines()
  lg.setColor(0, 0, 0, .22)
  for y = 0, H, 2 do lg.rectangle("fill", 0, y, W, 1) end
end

local function approach(v, t, d)
  if v < t then return min(t, v + d) else return max(t, v - d) end
end

---------------------------------------------------------------- звуки
local RATE = 16000
local function mk(dur, fn, vol)
  local n = floor(dur * RATE)
  local sd = love.sound.newSoundData(n, RATE, 16, 1)
  for i = 0, n - 1 do
    local v = fn(i / RATE, i / n)
    if v > 1 then v = 1 elseif v < -1 then v = -1 end
    sd:setSample(i, v)
  end
  local s = love.audio.newSource(sd)
  s:setVolume(vol or 1)
  return s
end

