local function getVol(name)
  return (VOL[name] or 1) * MASTER
end

local function loadVolumes()
  local data = love.filesystem.read("volumes.txt")
  if data then
    for line in data:gmatch("[^\n]+") do
      local k, v = line:match("([%w_]+)=([%d%.]+)")
      if k and v then
        local num = tonumber(v)
        if num then
          if k == "master" then MASTER = num else VOL[k] = num end
        end
      end
    end
  end
end

local function saveVolumes()
  local lines = {"master=" .. MASTER}
  for id, v in pairs(VOL) do lines[#lines+1] = id .. "=" .. v end
  love.filesystem.write("volumes.txt", table.concat(lines, "\n"))
end

local function resetVolumes()
  VOL = {}
  MASTER = 1
  saveVolumes()
end

