      local cat = CATEGORIES[idx]
      local y = 24 + (i-1) * itemH
      btn(8, y, 304, 16, cat.name, nil, nil, 8)
    end
    btn(8, 162, 100, 14, L("settings_back"))
    btn(212, 162, 100, 14, L("settings_reset"))
  else
    local cat = settings.cat
    T(cat.name, 0, 4, W, WHITE, 11)
    local itemH = 16
    local visible = 8
    local items = cat.items
    for i = 1, visible do
      local idx = settings.scroll + i
      if idx > #items then break end
      local item = items[idx]
      local y = 22 + (i-1) * itemH
      local vol = (item.id == "master") and MASTER or (VOL[item.id] or 1)
      local label = (item.name:find("^settings_") and L(item.name) or item.name)
      T(label, 6, y, 130, {.9,.9,.9}, 7, nil, "left")
      R(140, y+2, 110, 10, {.2,.2,.2})
      R(140, y+2, floor(110 * vol), 10, vol > 0.7 and {.3,.8,.3} or (vol > 0.3 and {.9,.7,.1} or {.9,.2,.2}))
      T(floor(vol*100) .. "%", 254, y, 60, WHITE, 7, nil, "left")
    end
    btn(8, 162, 100, 14, "← КАТЕГОРИИ")
    btn(212, 162, 100, 14, L("settings_reset"))
  end
  static(40, .15)
  lg.setColor(1,1,1)
  lg.draw(vig, 0, 0)
  scanlines()
end

local function pressSettings(x, y)
  if settings.mode == "cats" then
    if hit(x, y, 8, 162, 100, 14) then
      saveVolumes()
      state = "menu"
      menuAmbience()
      return
    end
    if hit(x, y, 212, 162, 100, 14) then
      resetVolumes()
      play("beep")
      return
    end
    local itemH = 18
    local visible = 8
    for i = 1, visible do
      local idx = settings.scroll + i
      if idx > #CATEGORIES then break end
      local iy = 24 + (i-1) * itemH
      if hit(x, y, 8, iy, 304, 16) then
        settings.cat = CATEGORIES[idx]
        settings.mode = "items"
        settings.scroll = 0
        play("beep")
        return
      end
    end
  else
    if hit(x, y, 8, 162, 100, 14) then
      settings.mode = "cats"
      settings.scroll = 0
      settings.cat = nil
      play("beep")
      return
    end
    if hit(x, y, 212, 162, 100, 14) then
      resetVolumes()
      play("beep")
      return
    end
    local itemH = 16
    local visible = 8
    local items = settings.cat.items
    for i = 1, visible do
      local idx = settings.scroll + i
      if idx > #items then break end
      local iy = 22 + (i-1) * itemH
      if hit(x, y, 140, iy+2, 110, 10) then
        local item = items[idx]
        local rel = (x - 140) / 110
        rel = max(0, min(1, rel))
        if item.id == "master" then
          MASTER = rel
        else
          VOL[item.id] = rel
        end
        saveVolumes()
        if item.id ~= "master" and item.id ~= "voice" and S[item.id] then
          play(item.id)
        elseif item.id == "voice" or item.id == "ring" then
          play("ring")
        end
        return
      end
    end
  end
  if y > 20 and y < 160 then
    settings.drag = true
    settings.lastY = y
  end
end


play = function(name, vol, pitch)
  local s = S[name]:clone()
  local base = vol or s:getVolume()
  local mult = getVol(name) * (ducked() and VOICE_DUCK or 1)
  s:setVolume(base * mult)
  if pitch then s:setPitch(pitch) end
  s:play()
end

local function nz() return rnd() * 2 - 1 end
local function saw(f, t) return ((f * t) % 1) * 2 - 1 end
local function tw(f, t) return sin(2 * pi * f * t) end

local function melody(notes, step, dur, vib, vol)
  return mk(#notes * step, function(t)
    local i = floor(t / step) + 1
    local nt = t % step
    local f = notes[i] * (1 + vib * sin(t * 6))
    return (sin(2 * pi * f * t) * .35 + sin(2 * pi * f * 2 * t) * .1) * math.exp(-nt * dur)
  end, vol)
end

LOOPS = {"hum", "fan", "box", "jingle", "buzz", "presence", "panelwork", "crackle", "scratch", "run", "menuamb"}

local function makeSounds()
  local ex = math.exp
  -- базовые
  S.hum = mk(3, function(t) return .2 * tw(55, t) + .08 * tw(110, t) end, .2)
  -- звук главного меню (если нет файла menu_ambience.mp3 — тихий шум)
  S.menuamb = mk(2, function(t) return nz() * .03 * (.6 + .4 * tw(.5, t)) end, .3)
  S.fan = mk(2, function(t) return nz() * .12 * (.6 + .4 * tw(8, t)) end, .35)
  S.buzz = mk(.5, function(t) return saw(120, t) * .12 end, .25)
  S.box = melody({523, 587, 659, 523, 659, 587, 523, 440}, .5, 5, 0, .3)
  S.jingle = melody({262, 311, 392, 311, 262, 233, 247, 196}, .6, 3, .004, .8)
  S.scream = mk(1.6, function(t, p)
    local f = 420 + 300 * sin(t * 45) + 700 * p
    return (saw(f, t) * .5 + saw(f * 1.5, t) * .25 + nz() * .5) * (1 - p * .5) * 1.4
  end, 1)
  S.step = mk(.25, function(t) return nz() * ex(-t * 14) * .4 + tw(55, t) * ex(-t * 12) * .8 end, .7)
  S.bang = mk(.5, function(t) return nz() * ex(-t * 10) * .7 + tw(40, t) * ex(-t * 8) end, .9)
  S.knock = mk(.35, function(t) return tw(80, t) * ex(-t * 12) + tw(160, t) * ex(-t * 20) * .5 end, .9)
  S.door = mk(.45, function(t) return nz() * ex(-t * 8) * .4 + tw(45, t) * ex(-t * 9) end, .8)
  S.beep = mk(.08, function(t) return tw(880, t) * .3 end, .5)
  S.tick = mk(.05, function(t) return tw(1400, t) * .25 end, .4)
  S.cam = mk(.3, function(t, p) return nz() * .5 * (1 - p) end, .6)
  S.heart = mk(.9, function(t)
    local a = ex(-t * 15) * tw(50, t)
    local t2 = t - .25
    local b = t2 > 0 and ex(-t2 * 15) * tw(45, t2) or 0
    return (a + b) * .9
  end, .9)
  S.whisper = mk(2.5, function(t) return nz() * (sin(t * 3) ^ 2) * .2 * (.5 + .5 * tw(6.4, t)) end, .6)
  S.growl = mk(1, function(t, p) return (saw(70 + 20 * sin(t * 30), t) * .6 + nz() * .2) * (1 - p) end, .8)
  S.chime = mk(2.5, function(t)
    local function bell(f, t0) local u = t - t0; return u > 0 and tw(f, u) * ex(-u * 2) * .4 or 0 end
    return bell(523, 0) + bell(659, .4) + bell(784, .8)
  end, .8)
  -- телефон: звонок перед записью и сигнал отбоя (когда запись кончилась или звонок сброшен)
  S.ring = mk(2.6, function(t)
    local function ringAt(t0)
      local u = t - t0
      if u < 0 or u > 1 then return 0 end
      local env = min(1, u * 40) * min(1, (1 - u) * 40)
      local gate = (floor(u * 40) % 2 == 0) and 1 or .3
      return (tw(1060, u) + tw(1400, u)) * .5 * gate * env
    end
    return (ringAt(0) + ringAt(1.3)) * .6
  end, .9)
  S.hangup = mk(.5, function(t)
    local v = nz() * ex(-t * 70) * .7 + tw(220, t) * ex(-t * 35) * .6
    local u = t - .12
    if u > 0 then v = v + nz() * ex(-u * 80) * .5 + tw(180, u) * ex(-u * 40) * .5 end
    u = t - .24
    if u > 0 and u < .22 then v = v + tw(425, u) * .25 * min(1, (.22 - u) * 30) end
    return v
  end, .9)
  -- планшет / камеры
  S.tablet = mk(.25, function(t, p) return (tw(180 + 700 * p, t) * .25 + nz() * .12) * (1 - p) end, .6)
  S.alarm = mk(.9, function(t) return (t % .3 < .18) and tw(1000, t) * .3 or 0 end, .7)
  S.camdie = mk(.8, function(t, p) return (nz() * .5 + saw(400 - 300 * p, t) * .3) * (1 - p) end, .8)
  S.repair = mk(.7, function(t, p)
    local k = (t % .09) / .09
    return (k < .25 and nz() * .5 or 0) + tw(300 + 500 * p, t) * .08
  end, .7)
  S.hiss = mk(1, function(t, p) return nz() * .35 * (1 - p) * (1 - p) end, .8)
  -- питание / щиток
  S.blackout = mk(2.2, function(t, p) return tw(30 + 300 * (1 - p) ^ 2, t) * .45 + nz() * .08 * (1 - p) end, 1)
  S.restore = mk(1.8, function(t, p)
    return tw(50 + 450 * p * p, t) * .35 * min(1, p * 3) + (p > .9 and nz() * .5 * (1 - p) * 10 or 0)
  end, .9)
  S.zap = mk(.8, function(t, p) return (nz() * .7 + tw(2000 - 1500 * p, t) * .4) * (1 - p) end, 1)
  -- тихая тревога: Оливер у щитка
  S.alarm = mk(.3, function(t, p)
    local f = (t < .13) and 980 or ((t < .16) and 0 or 740)
    return tw(f, t) * .35 * (1 - p * .5)
  end, .5)
  S.click = mk(.08, function(t) return nz() * ex(-t * 60) * .7 + tw(1200, t) * ex(-t * 50) * .3 end, .8)
  S.crackle = mk(1.2, function(t) return (rnd() < .006 and nz() or 0) * .8 + saw(60, t) * .05 end, .6)
  S.panelwork = mk(1.5, function(t)
    return saw(100, t) * .1 * (.5 + .5 * tw(3, t)) + (rnd() < .012 and nz() * .9 or 0)
  end, .7)
  S.dollleave = mk(1.6, function(t, p)
    local v = tw(700 - 580 * p, t) * .25 * (1 - p)
    for _, c in ipairs({.9, 1.3}) do
      local u = t - c
      if u > 0 then v = v + tw(140, u) * ex(-u * 12) * .8 + nz() * ex(-u * 30) * .3 end
    end
    return v
  end, .9)
  -- первый аниматроник в офисе: присутствие (глухие удары + хрип) и уход (визг + три шага + хлопок)
  S.presence = mk(2, function(t)
    local u = t % 1
    local th = ex(-u * 8) * tw(45, t) * .9
    local ra = (u > .3) and nz() * .15 * sin(pi * (u - .3) / .7) or 0
    return th + ra
  end, .9)
  S.enter = mk(1.2, function(t, p) return saw(110 + 40 * sin(t * 9), t) * .3 * (1 - p) + tw(45, t) * ex(-t * 5) * .6 end, .9)
  S.leave = mk(1.8, function(t)
    local v = 0
    if t < .7 then v = v + saw(600 + 900 * t, t) * .25 * (1 - t / .7) end
    for _, st in ipairs({.9, 1.15, 1.4}) do
      local u = t - st
      if u > 0 then v = v + tw(60, u) * ex(-u * 14) * .8 + nz() * ex(-u * 20) * .3 end
    end
    local u = t - 1.6
    if u > 0 then v = v + nz() * ex(-u * 10) * .6 + tw(40, u) * ex(-u * 8) end
    return v
  end, 1)
  -- вентиляция
  S.crawl = mk(.3, function(t) return nz() * ex(-t * 18) * .4 + tw(110, t) * ex(-t * 10) * .5 end, .6)
  S.hatch = mk(.5, function(t)
    return tw(220, t) * ex(-t * 6) * .6 + tw(330, t) * ex(-t * 9) * .3 + nz() * ex(-t * 20) * .3
  end, .8)
  -- наблюдатель у окна
  S.tap = mk(.2, function(t) return tw(900, t) * ex(-t * 40) * .6 + nz() * ex(-t * 60) * .3 end, .8)
  S.scratch = mk(1.2, function(t)
    return nz() * .3 * (sin(pi * 5 * t) ^ 2) + tw(2500 + 300 * sin(t * 20), t) * .08
  end, .7)
  S.glassbreak = mk(1, function(t) return nz() * ex(-t * 5) * .9 + tw(3000 + nz() * 500, t) * ex(-t * 12) * .3 end, 1)
  S.recoil = mk(.8, function(t, p) return (saw(300 - 200 * p, t) * .3 + nz() * .15) * (1 - p) end, .8)
  -- быстрый бегун
  S.run = mk(.8, function(t)
    local u = t % .2
    return tw(70, u) * ex(-u * 25) * .9 + nz() * ex(-u * 40) * .4
  end, .8)
  S.bump = mk(.7, function(t) return tw(45, t) * ex(-t * 7) + nz() * ex(-t * 15) * .6 end, 1)
  S.creak = mk(1, function(t, p) return saw(180 + 60 * sin(t * 7), t) * .15 * sin(pi * p) end, .6)
  S.prep = mk(1.5, function(t)
    return saw(55 + 10 * sin(t * 20), t) * .4 * (.5 + .5 * tw(3, t)) + nz() * .1
  end, .8)

  for _, n in ipairs(LOOPS) do S[n]:setLooping(true) end
end

stopLoops = function()
  for _, n in ipairs(LOOPS) do S[n]:stop() end
end

menuAmbience = function()
  archiveOk = false
  stopLoops()
  S.hum:setVolume(.12 * getVol("hum")); S.hum:play()
  S.menuamb:setVolume(.55 * getVol("menuamb")); S.menuamb:play()
end

local function play_loop(name, vol)
  local s = S[name]
  local mult = getVol(name) * (ducked() and VOICE_DUCK or 1)
  s:setVolume(vol * mult)
  if not s:isPlaying() then s:play() end
end

local function loop_off(name)
  if S[name]:isPlaying() then S[name]:stop() end
end

