local function bakeSprite(def)
  local pal = {}
  for k, v in pairs(def.pal) do pal[k] = hex(v) end
  local id = love.image.newImageData(32, #def.rows)
  for y = 1, #def.rows do
    local row = def.rows[y]
    for x = 1, 16 do
      local c = pal[row:sub(x, x)]
      if c then
        id:setPixel(x - 1, y - 1, c[1], c[2], c[3], 1)
        id:setPixel(32 - x, y - 1, c[1], c[2], c[3], 1)
      end
    end
  end
  local im = lg.newImage(id)
  im:setFilter("nearest", "nearest")
  return im
end

local IMG_SPRITES = {}  -- имена, у которых загружен внешний PNG
local PNG_NOTE = ""
-- у этих картинок голова вверху: скример центрируем по светящимся глазам
HEADLESS = {jack = true, archie = true, melody = true}
EYE = {jack = {.562, .181}, archie = {.608, .185}, melody = {.456, .173}}  -- запасные значения
-- ищем светящиеся глаза прямо в файле: так скример по центру, какой бы PNG ни лежал в проекте
-- глаза Мелоди: два самых плотных белых «кольца» в верхней части картинки (волосы и щёки их не сбивают)
local function findEyesRings(id, w, h)
  local lim = floor(h * .4)
  local step = max(1, floor(w / 400))
  local cell = max(4, floor(w * .03))
  local cols = floor(w / cell) + 1
  local pts, grid = {}, {}
  for y = 0, lim, step do
    for x = 0, w - 1, step do
      local r, g, b, a = id:getPixel(x, y)
      if a > .78 and r > .88 and g > .88 and b > .88 then
        pts[#pts + 1] = x; pts[#pts + 1] = y
        local k = floor(y / cell) * cols + floor(x / cell)
        grid[k] = (grid[k] or 0) + 1
      end
    end
  end
  local function peak(sx0, sy0)
    local best, bk = 0, nil
    for k, c in pairs(grid) do
      local cx, cy = (k % cols + .5) * cell, (floor(k / cols) + .5) * cell
      local skip = sx0 and ((cx - sx0) ^ 2 + (cy - sy0) ^ 2 < (w * .06) ^ 2)
      if c > best and not skip then best, bk = c, k end
    end
    if not bk then return nil end
    local cx0, cy0 = (bk % cols + .5) * cell, (floor(bk / cols) + .5) * cell
    local sx, sy, n = 0, 0, 0
    for i = 1, #pts, 2 do
      if (pts[i] - cx0) ^ 2 + (pts[i + 1] - cy0) ^ 2 < (w * .05) ^ 2 then
        sx = sx + pts[i]; sy = sy + pts[i + 1]; n = n + 1
      end
    end
    if n < 3 then return nil end
    return sx / n, sy / n
  end
  local x1, y1 = peak()
  if not x1 then return nil end
  local x2, y2 = peak(x1, y1)
  if not x2 then return nil end
  return {(x1 + x2) / 2 / w, (y1 + y2) / 2 / h}
end

local function findEyes(path, name)
  local ok, id = pcall(love.image.newImageData, path)
  if not ok or not id then return nil end
  local w, h = id:getDimensions()
  if name == "melody" then
    local ring = findEyesRings(id, w, h)
    if ring then return ring end
  end
  local lim = floor(h * ((name == "melody") and .42 or .30))
  local step = max(1, floor(w / 300))
  local sx, sy, n = 0, 0, 0
  for y = 0, lim, step do
    for x = 0, w - 1, step do
      local r, g, b, a = id:getPixel(x, y)
      if a > .78 then
        local hitp
        if name == "melody" then hitp = b > .9 and r > .67 and g < .78 and b - g > .196
        else hitp = b > .78 and r > .59 and g < .67 and b - g > .235 end
        if hitp then sx = sx + x; sy = sy + y; n = n + 1 end
      end
    end
  end
  if n < 3 then return nil end
  return {sx / n / w, sy / n / h}
end
local function scareAX(name, w)
  if HEADLESS[name] then return w * (EYE[name] or {.5, .25})[1] end
  return w / 2
end
local function scareEY(name) return (EYE[name] or {.5, .25})[2] end

local function spr(name, cx, cy, s, tint, a, rot)
  local im = SPR[name]
  local w, h = im:getDimensions()
  local t = tint or WHITE
  lg.setColor(t[1], t[2], t[3], a or 1)
  local scale = s
  -- полный спрайт из PNG: s = 1 это примерно 78 пикселей роста, без растяжения
  if IMG_SPRITES[name] and h > 0 then
    scale = s * (78 / h)
  end
  lg.draw(im, floor(cx), floor(cy), rot or 0, scale, scale, w / 2, h / 2)
end

BODY = {
  remy = {.27, .18, .11}, oliver = {.3, .32, .36}, melody = {.07, .07, .08},
  archie = {.1, .12, .18}, jack = {.32, .07, .07},
}

local function figure(name, cx, cy, s, k, rot, lean)
  lean = lean or 0
  if IMG_SPRITES[name] then
    spr(name, cx, cy + lean * s * .5, s, {k, k, k}, 1, rot)
    return
  end
  local c = BODY[name]
  local cc = {c[1] * k, c[2] * k, c[3] * k}
  if name == "melody" or name == "archie" then
    R(cx - 4 * s, cy + 14 * s, 8 * s, 50 * s, cc)
    R(cx - 20 * s, cy + 16 * s, 3 * s, 50 * s, cc)
    R(cx + 17 * s, cy + 16 * s, 3 * s, 50 * s, cc)
  else
    local bw = (name == "jack") and 11 or 15
    R(cx - bw * s, cy + (14 + lean) * s, bw * 2 * s, (38 - lean) * s, cc)
    R(cx - (bw + 7) * s, cy + (16 + lean) * s, 7 * s, 30 * s, cc)
    R(cx + bw * s, cy + (16 + lean) * s, 7 * s, 30 * s, cc)
    R(cx - 12 * s, cy + 52 * s, 10 * s, 24 * s, cc)
    R(cx + 2 * s, cy + 52 * s, 10 * s, 24 * s, cc)
  end
  spr(name, cx, cy + lean * s * .5, s, {k, k, k}, 1, rot)
end

-- переплёт и стекло окна поверх фигуры: Арчи виден именно за окном
local function drawWinBars(sx)
  R(sx, WIN.y, WIN.w, WIN.h, {.35, .4, .55}, .1)
  R(sx + WIN.w / 2 - 1, WIN.y, 2, WIN.h, {.18, .17, .2})
  R(sx, WIN.y + floor(WIN.h * .45), WIN.w, 2, {.18, .17, .2})
end

-- стоит на полу: feet — линия ступней, pxH — рост в пикселях, без искажения
local function placeFigure(name, x, feet, pxH, k, rot, lean)
  k = k or 1
  rot = rot or 0
  lean = lean or 0
  if IMG_SPRITES[name] then
    local im = SPR[name]
    local w, h = im:getDimensions()
    local scale = pxH / h
    lg.setColor(k, k, k, 1)
    lg.draw(im, floor(x), floor(feet), rot, scale, scale, w / 2, h)
    return
  end
  local s = pxH / 92
  figure(name, x, feet - 76 * s, s, k, rot, lean)
end

