local function wallQuad(side, x1, x2, f1, f2, col)
  local function pt(x, f)
    local a, b = x * 65 / 119, 180 - x * 66 / 119
    return a + (b - a) * f
  end
  local pts
  if side == "L" then
    pts = {x1, pt(x1, f1), x2, pt(x2, f1), x2, pt(x2, f2), x1, pt(x1, f2)}
  else
    pts = {W - x1, pt(x1, f1), W - x2, pt(x2, f1), W - x2, pt(x2, f2), W - x1, pt(x1, f2)}
  end
  lg.setColor(col[1], col[2], col[3], col[4] or 1)
  lg.polygon("fill", pts)
end

local function bakeHall(variant)
  local c = newCanvas(W, H)
  lg.setColor(.1, .11, .1); lg.polygon("fill", 0, 0, 119, 65, 119, 114, 0, 180)
  lg.setColor(.08, .09, .08); lg.polygon("fill", W, 0, 201, 65, 201, 114, W, 180)
  lg.setColor(.05, .06, .05); lg.polygon("fill", 0, 0, W, 0, 201, 65, 119, 65)
  lg.setColor(.13, .13, .12); lg.polygon("fill", 0, 180, W, 180, 201, 114, 119, 114)
  lg.setColor(0, 0, 0, .35)
  for i = -5, 5 do lg.line(160 + i * 7, 114, 160 + i * 62, 180) end
  for k = 1, 6 do local y = 114 + 66 * (k / 6) ^ 2; lg.line(0, y, W, y) end
  local warm = (variant == "W")
  local rg = love.math.newRandomGenerator(warm and 11 or 23)
  -- плиточный пол в перспективе (шахматка)
  local fa = warm and {.13, .12, .09} or {.09, .11, .13}
  local fb = warm and {.08, .075, .06} or {.06, .075, .09}
  for rI = 0, 5 do
    local y0 = 114 + 66 * (rI / 6) ^ 2
    local y1 = 114 + 66 * ((rI + 1) / 6) ^ 2
    local t0, t1 = (y0 - 114) / 66, (y1 - 114) / 66
    for ci = 0, 7 do
      local a0, a1 = ci / 8, (ci + 1) / 8
      local function px(t, a) return (119 + 82 * a) * (1 - t) + (320 * a) * t end
      local col = ((rI + ci) % 2 == 0) and fa or fb
      lg.setColor(col[1], col[2], col[3], 1)
      lg.polygon("fill", px(t0, a0), y0, px(t0, a1), y0, px(t1, a1), y1, px(t1, a0), y1)
    end
  end
  -- стены: тёмный низ-панель, поручень, пилястры
  local wc = warm and {.06, .05, .035} or {.035, .045, .06}
  lg.setColor(wc[1], wc[2], wc[3], 1)
  lg.polygon("fill", 0, 112, 119, 95, 119, 114, 0, 180)
  lg.polygon("fill", W, 112, 201, 95, 201, 114, W, 180)
  lg.setColor(.3, .28, .25, .8)
  lg.line(0, 112, 119, 95); lg.line(W, 112, 201, 95)
  lg.setColor(0, 0, 0, .55)
  for _, a in ipairs({26, 58, 86, 106}) do
    local ty, by = a * 65 / 119, 180 - a * 66 / 119
    lg.rectangle("fill", a - 2, ty, 4, by - ty); lg.rectangle("fill", W - a - 2, ty, 4, by - ty)
  end
  -- лампы на потолке и пятна света на полу
  local lc = warm and {1, .82, .45} or {.55, .75, 1}
  for _, y in ipairs({52, 36, 14}) do
    local lw = 10 + (65 - y) / 65 * 96
    local lh = 2 + (65 - y) / 65 * 6
    R(160 - lw / 2, y, lw, lh, lc, .55)
    local fy = 114 + (66 * (65 - y) / 65) * .85
    lg.setColor(lc[1], lc[2], lc[3], .07); lg.ellipse("fill", 160, fy, lw * 1.4, 4 + (65 - y) * .25)
  end
  -- царапины на стенах и тёмные пятна на полу
  lg.setColor(.02, .02, .02, .6)
  for _ = 1, 6 do
    local sx0, sy0 = rg:random(8, 100), rg:random(30, 100)
    lg.line(sx0, sy0, sx0 + rg:random(6, 12), sy0 + rg:random(10, 22)); lg.line(W - sx0, sy0, W - sx0 - rg:random(6, 12), sy0 + rg:random(10, 22))
  end
  lg.setColor(.22, .02, .03, .4)
  lg.ellipse("fill", warm and 118 or 214, 150, 18, 4); lg.ellipse("fill", warm and 132 or 200, 160, 9, 2)
  R(135, 68, 50, 46, {0, 0, 0})
  R(133, 66, 54, 3, {.2, .2, .22})
  -- в конце коридора: слабый свет и табличка «выход»
  R(139, 72, 42, 38, lc, .04)
  R(150, 61, 20, 4, {.05, .35, .1}); R(152, 62, 16, 2, {.4, 1, .5}, .5)
  if variant == "W" then
    wallQuad("L", 20, 56, .22, .62, {.75, .65, .45})
    wallQuad("L", 24, 52, .28, .56, {.4, .1, .15})
    wallQuad("R", 30, 70, .25, .5, {.04, .05, .04})
    wallQuad("R", 30, 70, .52, .58, {.15, .15, .15})
  else
    wallQuad("R", 20, 56, .2, .64, {.04, .04, .06})
    wallQuad("R", 24, 52, .25, .58, {.2, .3, .35, .5})
    wallQuad("L", 28, 62, .3, .6, {.6, .55, .4})
    wallQuad("L", 32, 58, .34, .56, {.1, .1, .1})
  end
  lg.setCanvas()
  return c
end

local function bakeStage()
  -- Главная сцена: бархатные кулисы с драпировкой, расписной задник, рампа, ферма с прожекторами
  local c = newCanvas(W, H)
  local rg = love.math.newRandomGenerator(3)
  R(0, 0, W, H, {.05, .04, .08})
  -- расписной задник: ночное небо, луна, холмы и ёлки
  for i = 0, 11 do R(40, 30 + i * 8, 240, 8, {.05 + .004 * i, .06 + .006 * i, .13 + .012 * i}) end
  for _ = 1, 30 do R(rg:random(44, 276), rg:random(32, 90), 1, 1, {.95, .9, .6}, .6) end
  lg.setColor(.78, .72, .5, .55); lg.circle("fill", 214, 54, 15)
