  -- пол сцены: доски с перспективой и рампа
  R(36, 118, 248, 62, {.2, .14, .09})
  for i = -6, 6 do lg.setColor(.08, .055, .035, .8); lg.line(160 + i * 10, 118, 160 + i * 28, 180) end
  for k = 1, 5 do local y = 118 + 62 * (k / 5) ^ 1.5; R(36, y, 248, 1, {.1, .07, .045}) end
  R(36, 115, 248, 4, {.34, .22, .13}); R(36, 119, 248, 1, {.5, .35, .2}, .5)
  -- лучи прожекторов: тёплый и два цветных
  lg.setColor(1, .95, .72, .075); lg.polygon("fill", 118, 38, 82, 124, 160, 124)
  lg.setColor(1, .95, .72, .075); lg.polygon("fill", 200, 38, 160, 124, 240, 124)
  lg.setColor(.9, .5, .55, .05); lg.polygon("fill", 70, 38, 40, 124, 100, 124)
  lg.setColor(.5, .6, 1, .05); lg.polygon("fill", 250, 38, 220, 124, 280, 124)
  lg.setColor(1, .95, .72, .05); lg.ellipse("fill", 120, 146, 52, 9); lg.ellipse("fill", 200, 146, 52, 9)
  for _ = 1, 26 do R(rg:random(70, 250), rg:random(45, 120), 1, 1, {1, .95, .7}, .35) end
  -- бархатные кулисы с складками и подхватами
  for side = 0, 1 do
    for i = 0, 17 do
      local x = side == 0 and (i * 3) or (W - 54 + i * 3)
      local fold = .5 + .5 * math.sin(i * 1.3 + side)
      R(x, 0, 3, H, {.27 + .2 * fold, .02, .05 + .03 * fold})
    end
    local tx = side == 0 and 56 or W - 56
    lg.setColor(.8, .62, .2, .9); lg.line(side == 0 and 0 or W, 92, tx, 112)
    R(tx - 2, 112, 4, 10, {.7, .55, .18})
