  -- ламбрекен сверху с золотой бахромой и вывеской
  R(0, 0, W, 24, {.34, .03, .07})
  for i = 0, 15 do lg.setColor(.5, .05, .1, 1); lg.circle("fill", i * 20 + 10, 24, 10) end
  R(0, 22, W, 2, {.75, .58, .2})
  R(88, 6, 144, 22, {.12, .06, .04}); R(90, 8, 140, 18, {.5, .1, .15})
  bakeText("SMILEY LAND", 90, 11, 140, {1, .9, .5}, 8)
  for i = 0, 17 do R(90 + i * 8, 4, 3, 3, {1, .85, .4}, .6); R(90 + i * 8, 27, 3, 3, {1, .85, .4}, .6) end
  -- огни рампы
  for i = 0, 12 do R(48 + i * 19, 174, 8, 3, {1, .75, .3}, .55) end
