end

local function bakeDining()
  -- Зал: праздничный обеденный зал, давно брошенный — гирлянды, шарики, столы со скатертями, лампы над столами
  local c = newCanvas(W, H)
  local rg = love.math.newRandomGenerator(31)
  -- задняя стена: полосатые обои и тёмная панель
  R(0, 0, W, 100, {.1, .07, .12})
  for x = 0, W, 16 do R(x, 0, 8, 100, {.115, .08, .135}) end
  R(0, 78, W, 22, {.07, .045, .08}); R(0, 77, W, 2, {.28, .2, .22})
  -- потолок и балки
  R(0, 0, W, 12, {.05, .035, .06})
  for x = 20, W, 60 do R(x, 0, 5, 12, {.03, .02, .035}) end
  -- рамки на стене: старые афиши
  R(24, 28, 26, 34, {.2, .17, .12}); R(26, 30, 22, 30, {.1, .08, .09}); R(30, 36, 14, 14, {.35, .12, .14}, .6)
  R(270, 26, 26, 36, {.2, .17, .12}); R(272, 28, 22, 32, {.1, .08, .09}); R(276, 34, 14, 16, {.15, .3, .5}, .6)
  -- арка в коридор (по центру)
  R(125, 46, 70, 54, {.03, .03, .04})
  R(121, 42, 78, 5, {.4, .1, .15}); R(121, 42, 4, 58, {.3, .08, .12}); R(195, 42, 4, 58, {.3, .08, .12})
  for i = 0, 8 do
    local bc = (i % 2 == 0) and {1, .8, .4} or {.6, .75, 1}
    R(126 + i * 8, 48, 3, 3, bc, .55)
  end
  -- гирлянды флажков: две провисающие линии
  for row = 0, 1 do
    local y0 = 6 + row * 10
    lg.setColor(.02, .02, .03, 1)
    for i = 0, 15 do
      local x0 = i * 20
      local sag = math.sin((i + .5) / 16 * math.pi) * 0
      local col = ({{.6, .1, .15}, {.15, .3, .6}, {.7, .6, .1}, {.2, .5, .25}})[(i + row) % 4 + 1]
      lg.setColor(col[1] * .65, col[2] * .65, col[3] * .65, 1)
      lg.polygon("fill", x0 + 2, y0 + 2 + sag, x0 + 18, y0 + 2 + sag, x0 + 10, y0 + 18 + sag)
    end
    lg.setColor(.03, .03, .04, 1); lg.line(0, y0 + 2, W, y0 + 2)
  end
  -- шарики по углам, часть сдулась
  local balloons = {{14, 60, {.6, .1, .15}}, {26, 52, {.15, .3, .6}}, {20, 70, {.7, .6, .1}},
                    {300, 58, {.15, .3, .6}}, {290, 50, {.6, .1, .15}}, {298, 70, {.2, .5, .25}}}
  for _, bl in ipairs(balloons) do
    lg.setColor(.02, .02, .03, 1); lg.line(bl[1], bl[2] + 8, bl[1] + rg:random(-3, 3), 92)
    lg.setColor(bl[3][1] * .6, bl[3][2] * .6, bl[3][3] * .6, 1); lg.ellipse("fill", bl[1], bl[2], 7, 9)
    lg.setColor(1, 1, 1, .12); lg.ellipse("fill", bl[1] - 2, bl[2] - 3, 2, 3)
  end
  -- пол: шахматная плитка в перспективе
  R(0, 100, W, 80, {.06, .06, .08})
  for rI = 0, 7 do
    local y0 = 100 + 80 * (rI / 8) ^ 1.6
    local y1 = 100 + 80 * ((rI + 1) / 8) ^ 1.6
    local t0, t1 = (y0 - 100) / 80, (y1 - 100) / 80
    for ci = -8, 7 do
      local function px(t, i) return 160 + i * (14 + 36 * t) end
      local col = ((rI + ci) % 2 == 0) and {.14, .13, .15} or {.055, .055, .075}
      lg.setColor(col[1], col[2], col[3], 1)
      lg.polygon("fill", px(t0, ci), y0, px(t0, ci + 1), y0, px(t1, ci + 1), y1, px(t1, ci), y1)
    end
  end
  -- лампы над столами и пятна света на полу
  for _, lx in ipairs({70, 160, 250}) do
    R(lx - 1, 12, 2, 18, {.03, .03, .04})
    lg.setColor(.1, .1, .12, 1); lg.polygon("fill", lx - 9, 36, lx + 9, 36, lx + 4, 28, lx - 4, 28)
    R(lx - 5, 36, 10, 2, {1, .85, .5}, .6)
    lg.setColor(1, .85, .5, .06); lg.polygon("fill", lx - 5, 37, lx + 5, 37, lx + 42, 150, lx - 42, 150)
  end
  -- столы: скатерть, стулья, колпаки, стаканчики и коробки из-под пиццы
  for _, p in ipairs({{70, 128}, {160, 152}, {250, 128}}) do
    local px, py = p[1], p[2]
    -- стулья позади стола
    for k = -1, 1, 2 do
      R(px + k * 34 - 5, py - 14, 10, 10, {.09, .06, .05}); R(px + k * 34 - 5, py - 20, 10, 3, {.12, .08, .06})
    end
    lg.setColor(.04, .04, .06, 1); lg.ellipse("fill", px, py + 34, 44, 8)
    -- скатерть свисает до пола
    R(px - 38, py + 2, 76, 24, {.3, .28, .3})
    for k = 0, 8 do R(px - 38 + k * 9.5, py + 2, 2, 24, {.2, .18, .2}) end
    lg.setColor(.5, .5, .55, 1); lg.ellipse("fill", px, py, 40, 12)
    lg.setColor(.68, .68, .72, 1); lg.ellipse("fill", px, py - 1, 36, 10)
    -- колпаки
    local hats = {{-18, {.8, .15, .2}}, {2, {.2, .4, .8}}, {18, {.8, .7, .15}}}
    for _, h in ipairs(hats) do
      lg.setColor(h[2][1] * .75, h[2][2] * .75, h[2][3] * .75, 1)
      lg.polygon("fill", px + h[1] - 4, py - 3, px + h[1] + 4, py - 3, px + h[1], py - 15)
    end
    R(px - 8, py - 3, 6, 4, {.8, .8, .85}); R(px + 6, py - 2, 5, 3, {.75, .75, .8})
    if px == 160 then R(px - 14, py - 5, 14, 6, {.55, .35, .2}) end
  end
  -- конфетти, пятна и паутина
  for _ = 1, 40 do
    local col = ({{.7, .15, .2}, {.2, .4, .8}, {.8, .7, .15}})[rg:random(1, 3)]
    R(rg:random(4, 316), rg:random(110, 176), 2, 1, {col[1] * .6, col[2] * .6, col[3] * .6}, .7)
  end
  lg.setColor(.2, .02, .03, .35); lg.ellipse("fill", 118, 170, 14, 3)
  lg.setColor(.5, .5, .55, .25)
  lg.line(0, 12, 20, 12, 0, 30); lg.line(0, 12, 16, 22); lg.line(W, 12, W - 22, 12, W, 32); lg.line(W, 12, W - 16, 24)
  lg.setCanvas()
  return c
end

local function bakePrize()
  -- Уголок призов: прилавок под полосатым навесом, неоновая вывеска, полки с подарками и плюшевыми игрушками
  local c = newCanvas(W, H)
  local rg = love.math.newRandomGenerator(11)
  R(0, 0, W, 128, {.055, .05, .09})
  for x = 0, W, 12 do R(x, 0, 6, 128, {.065, .055, .1}) end
  -- шашечная панель внизу стены
  for x = 0, W, 16 do for y = 104, 124, 10 do
    local alt = (floor(x / 16) + floor(y / 10)) % 2 == 0
    R(x, y, 16, 10, alt and {.1, .085, .12} or {.05, .04, .07})
  end end
  R(0, 102, W, 2, {.3, .2, .12})
  -- гирлянда с лампочками под потолком
  lg.setColor(.02, .02, .03, 1)
  for i = 0, 19 do
    local x1, x2 = i * 16, i * 16 + 16
    lg.line(x1, 5 + 3 * math.sin(i * .9), x2, 5 + 3 * math.sin((i + 1) * .9))
    local col = ({{1, .35, .4}, {.4, .6, 1}, {1, .85, .35}, {.4, 1, .55}})[i % 4 + 1]
    local by = 8 + 3 * math.sin((i + .5) * .9)
    R(x1 + 6, by, 3, 4, col, .65)
    lg.setColor(col[1], col[2], col[3], .08); lg.circle("fill", x1 + 7.5, by + 2, 6)
    lg.setColor(.02, .02, .03, 1)
  end
  -- неоновая вывеска
  R(114, 12, 92, 18, {.03, .02, .05}); R(114, 12, 92, 1, {.8, .3, .6}); R(114, 29, 92, 1, {.8, .3, .6})
  lg.setColor(1, .3, .65, .07); lg.rectangle("fill", 104, 6, 112, 32, 8, 8)
  bakeText("ПРИЗЫ", 114, 15, 92, {1, .45, .75}, 8)
  -- полосатый навес над прилавком
  for i = 0, 15 do
    local col = (i % 2 == 0) and {.6, .1, .15} or {.55, .52, .5}
    R(96 + i * 8, 34, 8, 12, col)
    lg.setColor(col[1], col[2], col[3], 1); lg.circle("fill", 100 + i * 8, 46, 4)
  end
  R(94, 32, 132, 3, {.3, .2, .12})
  -- полки по бокам: подарки с бантами и плюшевые мишки
  for sh = 0, 2 do
    R(10, 38 + sh * 28, 90, 4, {.3, .2, .1}); R(220, 38 + sh * 28, 90, 4, {.3, .2, .1})
    for g = 0, 4 do
      local col = ({{.7, .15, .2}, {.2, .4, .7}, {.8, .7, .2}, {.3, .6, .3}})[rg:random(1, 4)]
      for side = 0, 1 do
        local bx = (side == 0 and 14 or 224) + g * 17
        local by = 20 + sh * 28
        if g == 2 and sh == 1 then
          lg.setColor(.35, .22, .12, 1); lg.ellipse("fill", bx + 7, by + 13, 6, 6)
          lg.circle("fill", bx + 7, by + 6, 5); lg.circle("fill", bx + 3, by + 2, 2); lg.circle("fill", bx + 11, by + 2, 2)
          lg.setColor(.05, .03, .03, 1); lg.circle("fill", bx + 5, by + 5, 1); lg.circle("fill", bx + 9, by + 5, 1)
        else
          R(bx, by, 14, 18, col)
          R(bx + 6, by, 2, 18, {.9, .9, .8}); R(bx, by + 7, 14, 2, {.9, .9, .8})
          R(bx + 3, by - 3, 4, 3, {.9, .9, .8}); R(bx + 8, by - 3, 4, 3, {.9, .9, .8})
        end
      end
    end
  end
  -- аппараты: выдача билетиков и жетонов
  R(38, 100, 24, 28, {.13, .1, .16}); R(41, 104, 18, 8, {.1, .25, .3}); R(46, 116, 8, 3, {.8, .8, .75})
  R(262, 100, 24, 28, {.13, .1, .16}); R(265, 104, 18, 8, {.3, .15, .1}); R(270, 116, 8, 3, {.7, .6, .2})
  -- пол: плитка в перспективе
  R(0, 128, W, 52, {.07, .06, .09})
  for rI = 0, 4 do
    local y0 = 128 + 52 * (rI / 5) ^ 1.4
    local y1 = 128 + 52 * ((rI + 1) / 5) ^ 1.4
    local t0, t1 = (y0 - 128) / 52, (y1 - 128) / 52
    for ci = -8, 7 do
      local function px(t, i) return 160 + i * (20 + 30 * t) end
      local col = ((rI + ci) % 2 == 0) and {.11, .09, .13} or {.05, .04, .07}
      lg.setColor(col[1], col[2], col[3], 1)
      lg.polygon("fill", px(t0, ci), y0, px(t0, ci + 1), y0, px(t1, ci + 1), y1, px(t1, ci), y1)
    end
  end
  -- прилавок: стеклянная витрина и деревянный верх
  R(96, 128, 128, 6, {.34, .22, .12}); R(96, 128, 128, 1, {.55, .4, .25})
  R(98, 134, 124, 34, {.09, .07, .1}); R(100, 136, 120, 30, {.06, .05, .08})
  for i = 0, 8 do
    local col = ({{.7, .15, .2}, {.2, .4, .7}, {.8, .7, .2}})[i % 3 + 1]
    R(106 + i * 13, 150, 9, 9, col, .6); R(108 + i * 13, 145, 5, 5, col, .5)
  end
  R(96, 168, 6, 12, {.15, .1, .07}); R(218, 168, 6, 12, {.15, .1, .07})
  -- свет над прилавком, билетики и конфетти на полу
  lg.setColor(1, .9, .6, .05); lg.polygon("fill", 150, 40, 170, 40, 235, 150, 85, 150)
  for _ = 1, 22 do R(rg:random(10, 310), rg:random(136, 176), 4, 1, {.75, .72, .6}, .5) end
  lg.setCanvas()
  return c
end

