local function bakeSmallStage()
  -- Малая сцена: кукольный театрик — деревянная рама с звёздами, нити марионеток, табличка «ЗАКРЫТО»
  local c = newCanvas(W, H)
  local rg = love.math.newRandomGenerator(9)
  R(0, 0, W, H, {.045, .035, .06})
