---------------------------------------------------------------- логика игры
local CALLS_SECONDS = 7.5
-- Озвучка звонков: по одной записи на ночь, voice/<язык>/night<N>.mp3 (есть для ночей 1-5).
-- Если запись есть, она играет целиком, а текстовые субтитры не показываются (они не обязаны совпадать с записью).
-- Если записи нет, работают текстовые реплики из lang_*.lua.
VOICE_LEN = {106.6, 139.7, 94.5, 105.2, 80.2} -- запасная длина, если движок не вернул длительность
-- Ищем запись в нескольких местах: voice/<язык>/nightN.mp3, voice/nightN.mp3 и nightN.mp3 прямо в корне проекта.
local function voicePath(n)
  local p = string.format("voice/%s/night%d.mp3", curLang, n)
  if love.filesystem.getInfo(p) then return p end
  for _, q in ipairs({string.format("voice/night%d.mp3", n), string.format("night%d.mp3", n)}) do
    if love.filesystem.getInfo(q) then return q end
  end
  return p
end
local function hasVoice(n) return love.filesystem.getInfo(voicePath(n)) ~= nil end
-- План здания (в правом нижнем углу). Размер задаётся в паузе: VOL.camscale = 0.85 / 1 / 1.15
CAM_SIZES = {.85, 1, 1.15}
local function camSizeIndex()
  local cur = VOL.camscale or 1
  for i, v in ipairs(CAM_SIZES) do if math.abs(v - cur) < .01 then return i end end
  return 2
end
-- комнаты в базовых единицах {x, y, w, h}; всё плана занимает 112 x 96
--   сверху: малая сцена (К7), сцена (К1), уголок призов (К5)
--   в середине: зал (К2) во всю ширину
--   ниже: западный коридор (К3) | офис | восточный коридор (К4); под ними щиток (К6) и мастерская (К8)
CAM_PLAN = {
  [7] = {0, 0, 28, 22}, [1] = {32, 0, 44, 20}, [5] = {80, 0, 32, 26},
  [2] = {0, 28, 84, 20},
  [4] = {88, 30, 24, 40},                 -- восточный коридор: длинный, вдоль правой стены
  [3] = {0, 52, 26, 24},                  -- западный коридор: короче, с поворотом к офису
  [6] = {0, 80, 34, 16}, [8] = {78, 76, 34, 20},
  office = {38, 56, 36, 40},
}
CAM_SHORT = {"СЦЕНА", "ЗАЛ", "ЗАП.КОР.", "ВОСТ.КОР.", "ПРИЗЫ", "ЩИТОК", "М.СЦЕНА", "МАСТЕРСКАЯ"}
local function camGeomBase()
  local sc = CAM_SIZES[camSizeIndex()]
  return sc, 314 - 112 * sc, 158 - 96 * sc
end
local function camRect(id)
  local sc, x0, y0 = camGeomBase()
  local r = CAM_PLAN[id]
  return x0 + r[1] * sc, y0 + r[2] * sc, r[3] * sc, r[4] * sc
end

-- имена: ночь, в которую аниматроник представлен игроку (до неё показывается «???»)
INTRO_NIGHT = {remy = 1, oliver = 2, archie = 3, jack = 4, melody = 5}
DEFAULT_NAMES = {remy = "Реми", oliver = "Оливер", archie = "Арчи", jack = "Джек", melody = "Мелоди"}
-- имена берутся из языкового файла; если там таблицы names нет (старый lang_ru.lua) — запасные
local function animNames() return LT("names") or DEFAULT_NAMES end
local function animName(kind)
  if night >= (INTRO_NIGHT[kind] or 99) then return animNames()[kind] or DEFAULT_NAMES[kind] end
  return L("name_unknown")
end

local function msg(text, t) G.msg = text; G.msgT = t or 3 end
local function tip(key)
  -- подсказки отключены
end

-- один «критический момент» за раз: Дама у щитка / Наблюдатель у окна / Бегун в забеге
local function critFree() return G.crit == nil and G.critCool <= 0 and not G.black end
local function critSet(n) G.crit = n end
local function critClear(n) if G.crit == n then G.crit = nil; G.critCool = 2.5 end end

local function roomCam(name, e)
  if name == "remy" then
    if e.pos == 0 then return 1 elseif e.pos == 1 then return 2
    elseif e.pos == 2 then return 3 end  -- на камере виден в К3
  else
    if e.route == "door" then return ({[0] = 1, 2, 4})[e.pos] end
    return ({[0] = 1, 2, 3, 6})[e.pos]
  end
end

local function doorClosed(side)
  if side == "L" then return G.dL and G.pL >= .8 end
  return G.dR and G.pR >= .8
end

-- Баланс как в FNAF: у каждого аниматроника уровень ИИ (0-20) на каждую ночь.
-- Раз в ~5 секунд он бросает rnd(1,20); если выпало не больше его уровня, он делает шаг.
-- 0 = стоит на месте. Ночи: 1  2  3  4  5  6
AI = {
  remy   = {3, 5, 7, 9, 12, 16},
  oliver = {0, 4, 6, 8, 11, 15},
  wat    = {0, 0, 5, 7, 10, 14},
}
local function newGame()
  G = {
    time = 0, power = 100,
    dL = false, dR = false, pL = 0, pR = 0, hL = 0, hR = 0, kL = false, kR = false,
    lL = false, lR = false, lW = false,
    cam = false, sel = 1, camT = 0, camHeat = 0, camLock = false, camHot = false,
    broken = {}, warnId = nil, warnT = 0, breakT = (night >= 2) and rnd(50, 80) or 1e9,
    repairP = 0, rsT = 0,
    box = 100, boxZero = 0, boxWarnT = 0,
    out = false, outT = 0, outEnd = 12,
    black = false, mode = "office", vpos = 0, crawlT = 0, pz = nil, leverP = 0, lvT = 0,
    zapCd = 0, zapFx = 0, crit = nil, critCool = 0, hold = nil,
    off = {remy = 0, oliver = 0, archie = 0, jack = 0}, pcCd = 0, pcRepT = nil, reserve = false,
    camX = 50, flick = 0, glitch = 0, gk = "remy", halluc = 0, hk = 1, hb = 0,
    scareT = rnd(12, 25), intro = (night == 1) and 6 or 3.5, drag = false,
    voiceOn = (not CUSTOM) and night ~= 6 and hasVoice(night), call = ((not CUSTOM) and night ~= 6 and (hasVoice(night) or callList(night))) and 1 or nil, mono = (not CUSTOM and night == 6), monoT = 2.5, monoBegun = false, callT = CALLS_SECONDS, callBegun = false, mute = false, voice = nil,
    msg = nil, msgT = 0, tips = {},
    remy = {pos = 0, side = "L", mt = 6, dt = 0, seen = false, inOffice = false, officeT = 0, aggr = CUSTOM and CUSTOM.remy or (AI.remy[night] or 16)},
    oliver = {on = CUSTOM and CUSTOM.oliver > 0 or (not CUSTOM and night >= 2), route = "panel", dt = 0, pos = 0, mt = 8, zapT = 0, zapMax = 8, atPanel = false, stay = 0, aggr = CUSTOM and CUSTOM.oliver or (AI.oliver[night] or 15)},
    wat = {on = CUSTOM and CUSTOM.archie > 0 or (not CUSTOM and night >= 3), ws = 0, wp = 1, mt = 9, aggr = CUSTOM and CUSTOM.archie or (AI.wat[night] or 14), T = 0, Tmax = 5, litT = 0, tapT = 0},
    run = {on = CUSTOM and CUSTOM.jack > 0 or (not CUSTOM and night >= 4), rs = 0, u = 0, rp = 1},
  }
end

-- ---- двери: нагрев и перегрев (у каждой двери своя шкала)
local function updDoors(dt)
  G.pL = approach(G.pL, G.dL and 1 or 0, 3.5 * dt)
  G.pR = approach(G.pR, G.dR and 1 or 0, 3.5 * dt)
  local rate = 5 + .4 * night
  for _, s in ipairs({"L", "R"}) do
    local d, h, k = "d" .. s, "h" .. s, "k" .. s
    if G[d] then
      -- пока у двери стоит враг или бежит бегун, дверь не перегреется «в самый момент удара»
      local cap = (G.crit == "run" and s == "L") or (G.remy.pos == 3 and G.remy.side == s)
      G[h] = G[h] + rate * dt
      if cap and G[h] > 98 then G[h] = 98 end
      if G[h] >= 60 then tip("tip_door_heat") end
      if G[h] >= 100 then
        G[d] = false; G[k] = true
        play("hiss"); msg(L("msg_door_hot"), 3)
      end
    else
      G[h] = max(0, G[h] - (G[k] and 14 or 10) * dt)
      if G[k] and G[h] <= 25 then G[k] = false; play("beep", .4) end
    end
  end
end

-- ---- камеры: перегрев
local function updCamHeat(dt)
  if G.cam and not G.black and not G.camLock then
    G.camHeat = min(100, G.camHeat + (3.4 + .25 * night) * dt)
    if G.camHeat >= 80 and not G.camHot then
      G.camHot = true; play("alarm", .5); tip("tip_heat")
    end
    if G.camHeat >= 100 then
      G.camLock = true; G.hold = nil
      play("alarm", .9)
      msg(L("msg_cam_overheat"), 3.5)
    end
  else
    G.camHeat = max(0, G.camHeat - (G.camLock and 8 or 5.5) * dt)
    if G.camHeat < 70 then G.camHot = false end
    if G.camLock and G.camHeat <= 40 then
      G.camLock = false; play("beep", .5); msg(L("msg_cam_ready"), 2.5)
    end
  end
end

-- ---- камеры: поломка и ремонт
local function camSafeToBreak(id)
  if G.broken[id] then return false end
  if id == 6 and G.oliver.on and G.oliver.pos >= 2 then return false end
  if id == 7 and G.run.on and G.run.rs >= 1 then return false end
  if id == 8 and G.wat.on and G.wat.ws >= 1 then return false end
  if id == 5 and G.box < 45 then return false end
  return true
end

local function brokenCount()
  local n = 0
  for _ in pairs(G.broken) do n = n + 1 end
  return n
end

local function updBreaks(dt)
  if night >= 2 and not G.black then
    if G.warnId then
      G.warnT = G.warnT - dt
      if G.warnT <= 0 then
        G.broken[G.warnId] = true
        if G.cam and G.sel == G.warnId then G.camT = .3 end
        play("camdie")
        msg(L("msg_cam_broken", G.warnId), 3.5)
        G.warnId = nil; G.breakT = rnd(50, 80)
      end
    else
      G.breakT = G.breakT - dt
      if G.breakT <= 0 then
        local maxB = (night >= 3) and 2 or 1
        if brokenCount() >= maxB then
          G.breakT = rnd(20, 40)
        else
          local c = {}
          for i = 1, 8 do if camSafeToBreak(i) then c[#c + 1] = i end end
          if #c > 0 then
            G.warnId = c[rnd(1, #c)]; G.warnT = 2
            play("camdie", .25, 2)
          else
            G.breakT = 10
          end
        end
      end
    end
  end
  if G.hold == "repair" and G.cam and G.broken[G.sel] and G.camT <= 0 then
    G.repairP = G.repairP + dt / 3
    G.rsT = G.rsT - dt
    if G.rsT <= 0 then G.rsT = .3; play("repair", .5) end
    if G.repairP >= 1 then
      local id = G.sel
      G.broken[id] = nil; G.repairP = 0; G.hold = nil
      play("repair", .9); msg(L("msg_cam_fixed", id), 2.5)
    end
  else
    G.repairP = max(0, G.repairP - dt * .6)
  end
end

local function startLine()
  play("tick")
  if G.voice then G.voice:stop(); G.voice = nil end
  if G.voiceOn then
    -- вся запись ночи одним куском; конец звонка по длительности записи
    local ok, src = pcall(love.audio.newSource, voicePath(night), "stream")
    if ok and src then
      G.voice = src
      src:setVolume(getVol("voice"))
      src:play()
      local d = src:getDuration()
      if not d or d <= 0 then d = VOICE_LEN[night] or 90 end
      G.callT = d + .5
    else
      G.voiceOn = false -- файл не открылся: переходим на текстовые реплики
      if not callList(night) then G.call = nil; return end
    end
  end
  if not G.voiceOn then
    local list = callList(night)
    local text = list and list[G.call] or ""
    G.callT = 4.5 + #text / 32
  end
end

-- ---- вторая: щиток, разряд, отключение питания
local function cutPower()
  local d = G.oliver
  critClear("oliver")
  G.black = true
  d.route = "panel"; d.atPanel = true; d.stay = rnd(16, 24); d.pos = 3; G.ventWarned = false
  G.cam = false; G.lL = false; G.lR = false; G.lW = false; G.hold = nil
  play("blackout", 1)
end

local function doZap()
  if G.zapCd > 0 then return end
  G.zapCd = 6; G.zapFx = .45
  G.power = max(.5, G.power - 2)
  play("zap", 1)
  local d = G.oliver
  if d.on and d.pos == 3 and d.route ~= "door" and not G.black then
    d.pos = 0; d.mt = rnd(16, 24)
    critClear("oliver"); play("recoil", .8)
    msg(L("msg_zap_ok"), 3)
  else
    msg(L("msg_zap_miss"), 2.5)
  end
end

local function restorePower()
  G.black = false; G.hold = nil
  if G.pz then G.pz.done = true end
  local d = G.oliver
  d.pos = 0; d.mt = rnd(18, 26); d.atPanel = false
  loop_off("panelwork")
  play("restore", 1)
end

local function startPanel()
  G.mode = "panel"; G.leverP = 0; G.hold = nil
  local o = {1, 2, 3}
  for i = 3, 2, -1 do local j = rnd(1, i); o[i], o[j] = o[j], o[i] end
  G.pz = {num = o, next = 1, on = {false, false, false}, ready = false, done = false}
  play("hatch", .9)
  tip("tip_panel")
end

local function tapBreaker(i)
  local pz = G.pz
  if not pz or pz.on[i] or pz.done then return end
  if pz.num[i] == pz.next then
    pz.on[i] = true; pz.next = pz.next + 1; play("click", .8)
    if pz.next > 3 then pz.ready = true end
  else
    pz.on = {false, false, false}; pz.next = 1; pz.ready = false
    play("zap", .5, 1.4); G.zapFx = .25
    msg(L("msg_panel_wrong"), 3)
  end
end

-- ---- первый (Grin): сцена -> зал -> коридор -> дверь; может проникнуть в офис, пока игрок в вентиляции
-- Время (сек), с которого аниматроник начинает двигаться. С 4-й ночи они просыпаются по очереди.
function boxOn() return (CUSTOM and CUSTOM.melody > 0) or (not CUSTOM and night == 5) end
function jackN() return CUSTOM and (1 + 5 * CUSTOM.jack / 20) or night end
function nightText() return CUSTOM and (CUSTOM.challengeName or "СВОЯ НОЧЬ") or L("night_n", night) end
function wakeT(name)
  if CUSTOM then return 15 end
  local t = {
    [4] = {remy = 100, oliver = 130, archie = 170, jack = 210},
    [5] = {remy = 100, oliver = 120, archie = 145, jack = 175},
    [6] = {remy = 100, oliver = 110, archie = 125, jack = 145},
  }
  local row = t[night]
  return (row and row[name]) or 100
end
function isOff(name) return G.off and G.off[name] and G.off[name] > 0 end

local function updGrin(dt)
  local e = G.remy
  if G.time < wakeT("remy") or isOff("remy") then return end
  if e.inOffice then
    e.officeT = e.officeT - dt
    if e.officeT <= 0 then
      e.inOffice = false; e.pos = 1; e.mt = 9; e.dt = 0; e.seen = false
      play("leave", 1) -- отчётливый звук ухода
    end
    return
  end
  if e.pos < 3 then
    local watched = G.cam and G.camT <= 0 and not G.broken[G.sel] and G.sel == roomCam("remy", e)
    if not watched then e.mt = e.mt - dt end
    if e.mt <= 0 then
      e.mt = 4.97
      if rnd(1, 20) <= e.aggr then
        e.pos = e.pos + 1
        if e.pos == 2 then e.side = "L"; play("step", .6) end  -- Реми всегда у левой двери
        if e.pos == 3 then
          e.dt = 0; e.seen = false; play("step", 1); play("whisper", .6)
          if S.remydoor then play("remydoor", 1) end  -- сигнал: Реми появился у двери (один раз при прибытии)
        end
      end
    end
  else
    local lit = (e.side == "L" and G.lL) or (e.side == "R" and G.lR)
    if lit and not e.seen then e.seen = true; play("growl", .8); G.flick = .2 end
    e.dt = e.dt + dt
    if e.dt > max(2.8, 4.5 - night * .35) then
      if doorClosed(e.side) then
        e.pos = 1; e.mt = 7; e.dt = 0; e.seen = false
        play("knock", 1)
      elseif G.mode == "office" or G.mode == "pc" then
        scare("remy")
      else
        e.inOffice = true; e.officeT = rnd(14, 22)
        play("enter", 1)
      end
    end
  end
end

local function updDoll(dt)
  local d = G.oliver
  if not d.on or G.time < wakeT("oliver") or isOff("oliver") then return end
  if G.black then
    if d.atPanel then
      d.stay = d.stay - dt
      if d.stay <= 0 then
        d.atPanel = false; d.pos = 0; d.mt = rnd(18, 26)
        play("dollleave", 1) -- отдельный звук ухода от щитка
      end
    end
    return
  end
  if d.pos < 3 then
    d.mt = d.mt - dt
    if d.mt <= 0 then
      d.mt = 4.98
      if rnd(1, 20) <= d.aggr then
        if d.pos == 2 and d.route == "door" then
          d.pos = 3; d.dt = 0; play("step", 1)
          if S.olivdoor then play("olivdoor", 1) end  -- сигнал: Оливер у правой двери (один раз при прибытии)
        elseif d.pos == 2 then
          if critFree() then
            d.pos = 3; d.zapMax = max(5.5, 10 - night * .8); d.zapT = d.zapMax
            critSet("oliver"); play("step", 1); G.flick = .2
            tip("tip_doll")
          end
        else
          d.pos = d.pos + 1
          if d.pos == 1 then d.route = (rnd() < .5) and "door" or "panel" end
          if d.pos == 2 then play("step", .5) end
        end
      end
    end
  elseif d.route == "door" then
    d.dt = d.dt + dt
    if d.dt > max(3.2, 5 - night * .3) then
      if doorClosed("R") then
        d.pos = 0; d.mt = rnd(14, 22); d.dt = 0; play("knock", 1)
      elseif G.mode == "office" or G.mode == "pc" then
        scare("oliver")
      else
        d.pos = 0; d.mt = rnd(14, 22); d.dt = 0
      end
    end
  else
    d.zapT = d.zapT - dt
    -- небольшая тихая тревога, пока Оливер у щитка
    G.alarmT = (G.alarmT or 0) - dt
    if G.alarmT <= 0 then G.alarmT = 1.2; play("alarm", .22) end
    if d.zapT <= 0 then cutPower() end
  end
end

-- ---- наблюдатель у окна: ожидание -> приближение -> наблюдение -> угроза
local function updWat(dt)
  local w = G.wat
  if not w.on or G.black or G.time < wakeT("archie") or isOff("archie") then return end
  if w.ws < 2 then
    w.mt = w.mt - dt
    if w.mt <= 0 then
      w.mt = 5.0
      if w.ws == 0 and rnd() < .4 then
        w.wp = (w.wp == 1) and 2 or 1; play("step", .25, .6)
      elseif rnd(1, 20) <= w.aggr then
        if w.ws == 0 then
          w.ws = 1; play("step", .4, .6)
        elseif critFree() then
          w.ws = 2; w.T = rnd(6, 9); w.Tmax = w.T; w.tapT = 1.6; w.litT = 0
          critSet("wat"); play("tap", 1); tip("tip_wat")
        end
      end
    end
  elseif w.ws == 2 then
    w.T = w.T - dt; w.tapT = w.tapT - dt
    if w.tapT <= 0 then w.tapT = 1.6; play("tap", .9) end
    if w.T <= 0 then w.ws = 3; w.Tmax = max(3.8, 5.2 - .3 * night); w.T = w.Tmax; w.litT = 0 end
  else
    w.T = w.T - dt
    if w.T <= 0 then play("glassbreak", 1); scare("archie") return end
  end
  if w.ws >= 2 then
    if G.lW then w.litT = w.litT + dt else w.litT = max(0, w.litT - dt) end
    if w.litT >= 1 then
      w.ws = 1; w.mt = rnd(10, 16); w.litT = 0
      critClear("wat"); loop_off("scratch"); play("recoil", 1)
    end
  end
end

-- ---- быстрый бегун: не любит, когда за ним долго не следят
local function updRun(dt)
  local r = G.run
  if not r.on or G.black or G.time < wakeT("jack") or isOff("jack") then return end
  if r.rs < 3 then
    local watched = G.cam and G.camT <= 0 and G.sel == 7 and not G.broken[7]
    if watched then r.u = max(-15, r.u - 3 * dt) else r.u = r.u + 2.2 * dt end
    local T1 = 16 - jackN()
    local T2 = T1 + 8
    local ns = (r.u >= T2) and 2 or ((r.u >= T1) and 1 or 0)
    if ns > r.rs then
      if ns == 1 then play("creak", .3) else play("prep", .35) end
    end
    r.rs = ns
    if r.u >= T2 + 10 and critFree() and not G.kL then
      r.rs = 3; r.rp = 1; critSet("run"); tip("tip_run")
    end
  else
    r.rp = r.rp - dt / (10 - .5 * jackN())  -- ~7 с на 6-й ночи, ~9 с на 1-й
    if r.rp <= 0 then
      loop_off("run")
      if doorClosed("L") then
        play("bump", 1); shake = .6
        r.rs = 0; r.u = -12; r.rp = 1
        critClear("run")
      else
        scare("jack")
      end
    end
  end
end

-- ---- вентиляция
local function updVent(dt)
  if G.mode ~= "vent" then return end
  local dir = 0
  if G.hold == "vl" then dir = -1 elseif G.hold == "vr" then dir = 1 end
  if dir ~= 0 then
    G.vpos = max(0, min(1, G.vpos + dir * .11 * dt))
    G.crawlT = G.crawlT - dt
    if G.crawlT <= 0 then G.crawlT = .55; play("crawl", .5, .9 + rnd() * .2) end
  end
end

local function updPanel(dt)
  if G.mode ~= "panel" or not G.pz then return end
  local pz = G.pz
  if G.hold == "lever" and pz.ready and not pz.done then
    G.leverP = min(1, G.leverP + dt / 2)
    G.lvT = G.lvT - dt
    if G.lvT <= 0 then G.lvT = .25; play("click", .5, .6 + G.leverP * .6) end
    if G.leverP >= 1 then restorePower() end
  else
    G.leverP = max(0, G.leverP - dt * 1.5)
  end
end

-- ---- громкость зацикленных звуков (звук помогает ориентироваться, даже без камер)
local function audioUpdate()
  if G.out then return end
  local d, w, r, g = G.oliver, G.wat, G.run, G.remy
  if not G.black then
    play_loop("fan", .35)
    S.hum:setVolume(.2 * getVol("hum"))
  else
    loop_off("fan"); loop_off("buzz")
    S.hum:setVolume(.08 * getVol("hum"))
  end
  if (G.lL or G.lR or G.lW) and not G.black then play_loop("buzz", .6) else loop_off("buzz") end
  if d.on and d.pos == 3 and d.route ~= "door" and not G.black then
    play_loop("crackle", .35 + .5 * (1 - d.zapT / max(1, d.zapMax)))
  else
    loop_off("crackle")
  end
  if w.on and w.ws == 3 and not G.black then play_loop("scratch", .7) else loop_off("scratch") end
  if r.on and r.rs == 3 then
    local k = 1 - r.rp
    S.run:setPitch(RUN_FILE and 1 or (.9 + .6 * k))
    play_loop("run", .5 + .5 * k)
  else
    loop_off("run")
  end
  if g.inOffice then
    local v = 1
    if G.mode == "vent" then v = .25 + .75 * (1 - G.vpos) elseif G.mode == "panel" then v = .15 end
    play_loop("presence", v)
  else
    loop_off("presence")
  end
  if d.atPanel and G.black then
    local v = .15
    if G.mode == "vent" then v = .1 + .9 * G.vpos elseif G.mode == "panel" then v = 1 end
    play_loop("panelwork", v)
  else
    loop_off("panelwork")
  end
end

function playScare(kind)
  local src = SCARES and SCARES[kind]
  if src then
    local c = src:clone(); c:setVolume(getVol("scream")); c:play()
  else
    play("scream", 1)
  end
end

scare = function(kind)
  state = "jump"
  jump = {t = 0, kind = kind}
  shake = 1
  stopLoops()
  if G and G.voice then G.voice:stop() end
  playScare(kind)
end

win = function()
  state = "win"; winT = 0; winChime = false
  -- прошёл 6-ю ночь: открывается «Своя ночь» в главном меню
  if night >= 6 and not CUSTOM and not customUnlocked then
    customUnlocked = true; customJustUnlocked = true
    love.filesystem.write("custom_unlock.txt", "1")
  end
  -- челлендж пройден: запоминаем
  if CUSTOM and CUSTOM.challenge then CN_DONE[CUSTOM.challenge] = true; saveCustomDone() end
  stopLoops()
  if G.voice then G.voice:stop() end
  if night >= maxNight then
    maxNight = nextAvailableNight(night) or night
    love.filesystem.write("save.txt", tostring(maxNight)); love.filesystem.write("save.bak", tostring(maxNight))
  end
  local st = LT("story")
  story.pages = (not CUSTOM and type(st) == "table" and st[night]) or nil
  story.i = 1
end

startNight = function()
  if night == 6 and not CUSTOM and not archiveOk then startArchive() return end
  newGame()
  state = "game"
  stopLoops()
  S.hum:setVolume(.2 * getVol("hum")); S.hum:play()
  S.fan:play()
  if boxOn() then S.box:setVolume(.1 * getVol("box")); S.box:play() end
end

local function afterWin()
  if WIN6 then WIN6:stop(); WIN6 = nil end
  customJustUnlocked = false
  if CUSTOM then CUSTOM = nil; night = 1; state = "menu"; selNight = maxNight; menuAmbience()
  else
    local nextNight = nextAvailableNight(night)
    if nextNight then night = nextNight; startNight()
    else night = 1; state = "menu"; selNight = maxNight; menuAmbience() end
  end
end

-- внутренняя речь Майлза в начале 6-й ночи (его собственные мысли, не телефонный звонок)
function startMono()
  for _, p in ipairs({"Miles_Fear_Reaction.mp3", "voice/Miles_Fear_Reaction.mp3", "voice/miles_fear_reaction.mp3"}) do
    if love.filesystem.getInfo(p) then
      local ok, src = pcall(love.audio.newSource, p, "stream")
      if ok and src then
        G.voice = src
        src:setVolume(getVol("voice"))
        src:play()
      end
      return
    end
  end
end

local function updateGame(dt)
  if G.intro > 0 then G.intro = G.intro - dt return end
  if G.mono and not G.monoBegun then
    G.monoT = G.monoT - dt
    if G.monoT <= 0 then G.monoBegun = true; startMono() end
  end
  if G.call == 1 and not G.callBegun then
    -- как во FNAF: сначала звонит телефон, потом начинается запись
    G.callBegun = true; G.ringT = 2.7
    G.ringSrc = S.ring:clone()
    G.ringSrc:setVolume(getVol("ring"))
    G.ringSrc:play()
  end
  if G.ringT then
    G.ringT = G.ringT - dt
    if G.ringT <= 0 then
      G.ringT = nil; G.ringSrc = nil
      if G.call and not G.mute then startLine() end
    end
  end
  G.time = G.time + dt
  if G.time >= NIGHT_LEN then win() return end
  for _, k in ipairs({"flick", "halluc", "camT", "glitch", "zapFx", "zapCd", "critCool", "msgT"}) do
    if G[k] > 0 then G[k] = max(0, G[k] - dt) end
  end

  updDoors(dt)
  updCamHeat(dt)
  updBreaks(dt)
  for k, v in pairs(G.off) do if v > 0 then G.off[k] = max(0, v - dt) end end
  if G.pcCd > 0 then G.pcCd = max(0, G.pcCd - dt) end
  if G.pcRepT and G.mode == "pc" then
    G.pcRepT = G.pcRepT - dt
    if G.pcRepT <= 0 then
      G.pcRepT = nil; G.broken = {}; G.repairP = 0
      play("repair", .9); msg("Камеры исправлены.", 2.5)
    end
  end

  -- телефонный разговор
  if G.call and not G.mute and not G.ringT then
    G.callT = G.callT - dt
    if G.callT <= 0 then
      G.call = G.call + 1
      local list = callList(night)
      if G.voiceOn or not list or not list[G.call] then
        G.call = nil
        if G.voice then G.voice:stop(); G.voice = nil end
        play("hangup")
      else
        startLine()
      end
    end
  end

  -- батарея (прежняя механика)
  if not G.out then
    local use = (G.dL and 1 or 0) + (G.dR and 1 or 0) + (G.lL and 1 or 0)
      + (G.lR and 1 or 0) + (G.lW and 1 or 0) + (G.cam and 1 or 0)
    G.power = G.power - .15 * use * (1 + .06 * (night - 1)) * dt
    if G.power <= 0 then
      G.power = 0; G.out = true; G.outEnd = rnd(10, 16)
      G.dL, G.dR, G.lL, G.lR, G.lW, G.cam = false, false, false, false, false, false
      G.hold = nil
      stopLoops(); play("door"); S.jingle:setVolume(getVol("jingle")); S.jingle:play()
    end
  else
    G.outT = G.outT + dt
    G.pL = approach(G.pL, 0, 3.5 * dt); G.pR = approach(G.pR, 0, 3.5 * dt)
    if G.outT > 4 and rnd() < dt * 2 then G.flick = .15 end
    if G.outT > G.outEnd then
      if (CUSTOM and CUSTOM.remy == 0) or isOff("remy") then
        -- Реми в этой ночи не активен: питание просто возвращается
        G.out = false; G.outT = 0; G.power = 8
        play("restore", 1)
      else
        scare("remy")
      end
    end
    return
  end

  -- музыкальная шкатулка: только на 5-й ночи
  if boxOn() then
    if G.time < (CUSTOM and 15 or 100) then
      -- до 2:00 шкатулка не садится
      G.box = 100
      S.box:setVolume(.1 * getVol("box"))
    else
      local rate = (.9 + .3 * (CUSTOM and (1 + 4 * CUSTOM.melody / 20) or night)) * (G.black and .5 or 1)
      if G.hold == "wind" and G.cam and G.sel == 5 and G.camT <= 0 and not G.broken[5] then
        G.box = min(100, G.box + 32 * dt)
      else
        G.box = max(0, G.box - rate * dt)
      end
      if G.box <= 0 then
        if not G.black then G.boxZero = G.boxZero + dt end
        if G.boxZero > 8 then scare("melody") return end
      else
        G.boxZero = 0
      end
      if G.box < 30 then
        tip("tip_box")
        G.boxWarnT = G.boxWarnT - dt
        if G.boxWarnT <= 0 then G.boxWarnT = 8; play("whisper", .4) end
      end
      S.box:setVolume(((G.box / 100) * (.1 + ((G.cam and G.sel == 5) and .5 or 0)) * (G.black and .3 or 1)) * getVol("box"))
      S.box:setPitch(.7 + .3 * G.box / 100)
    end
  else
    G.box = 100
    S.box:setVolume(0)
  end

  updGrin(dt)
  if state ~= "game" then return end
  updDoll(dt)
  if state ~= "game" then return end
  updWat(dt)
  if state ~= "game" then return end
  updRun(dt)
  if state ~= "game" then return end
  updVent(dt)
  updPanel(dt)
  if G.mode == "office" and not G.cam then
    if G.hold == "scrL" then G.camX = max(0, G.camX - 260 * dt)
    elseif G.hold == "scrR" then G.camX = min(OW - W, G.camX + 260 * dt) end
  end

  -- защита от «отсидки» в вентиляции: нельзя дожидаться утра вне офиса
  if G.mode == "vent" or G.mode == "panel" then G.ventT = (G.ventT or 0) + dt else G.ventT = 0 end
  if G.black then G.blackT = (G.blackT or 0) + dt else G.blackT = 0 end
  -- эти «лимиты времени» — часть угрозы Реми: если он выключен (уровень 0 или отключён через ПК), они не убивают
  local remyOn = not ((CUSTOM and CUSTOM.remy == 0) or isOff("remy"))
  if not remyOn then G.ventT = 0; G.blackT = 0 end
  if G.ventT > 50 then scare("remy") return end
  if G.blackT > 70 then scare("remy") return end
  -- предупреждение: когда время почти вышло, слышно сердцебиение
  local nearRemy = remyOn and (G.ventT > 36 or G.blackT > 56)

  -- пока кто-то стоит у двери, слышно сердце
  local remyDoor = G.remy.pos == 3 and not G.remy.inOffice
  if remyDoor or nearRemy or G.crit ~= nil then
    G.hb = G.hb - dt
    if G.hb <= 0 then
      local fast = (G.wat.ws == 3) or (G.run.rs == 3 and G.run.rp < .4)
      G.hb = fast and .6 or .9
      play("heart", (remyDoor or nearRemy) and 1 or .65)
    end
  end

  -- далёкие шумы театра: скрип, шаги, стук, шёпот (тихо, чтобы пугало не звуком, а ожиданием)
  G.ambT = (G.ambT or rnd(10, 18)) - dt
  if G.ambT <= 0 then
    G.ambT = rnd(max(7, 16 - night * 1.5), max(14, 32 - night * 3))
    local a = rnd(1, 5)
    if a == 1 then play("creak", .16, .7)
    elseif a == 2 then play("step", .12, .5)
    elseif a == 3 then play("tap", .1, .5)
    elseif a == 4 then play("whisper", .12, .8)
    else play("bang", .14, .6) end
  end

  -- случайная жуть (реже и мягче)
  G.scareT = G.scareT - dt
  if G.scareT <= 0 then
    G.scareT = rnd(25, 45)
    local r = rnd(1, 5)
    if r == 1 then play("whisper", .5); G.flick = .35
    elseif r == 2 then play("whisper", .4)
    elseif r == 3 then play("bang", .55)
    end
    if G.cam and rnd() < .4 then G.glitch = .1; G.gk = ({"remy", "oliver", "melody"})[rnd(1, 3)] end
  end

  audioUpdate()
end

---------------------------------------------------------------- ввод
local function openCam()
  if clock - (G.camTog or -1) < .25 then return end
  if G.black and G.mode ~= "vent" then msg(L("msg_no_power"), 2) return end
  G.camTog = clock
  G.cam = true; G.lL = false; G.lR = false; G.lW = false
  G.camT = .25; G.repairP = 0
  play("tablet", .6, 1); play("cam", .5)
end

local function closeCam()
  if clock - (G.camTog or -1) < .25 then return end
  G.camTog = clock
  G.cam = false; G.hold = nil; G.camT = .2
  play("tablet", .6, .7)
end

local function setLight(which)
  play(S.lightbtn and "lightbtn" or "beep", 1)  -- звук нажатия на кнопку света
  if G.black then msg(L("msg_no_power"), 2) return end
  local cur = (which == "L" and G.lL) or (which == "R" and G.lR) or (which == "W" and G.lW)
  G.lL, G.lR, G.lW = false, false, false
  if not cur then
    if which == "L" then G.lL = true elseif which == "R" then G.lR = true else G.lW = true end
  end
end

local function toggleDoor(s)
  local k = (s == "L") and G.kL or G.kR
  if k then msg(L("msg_door_cool"), 2) play("beep", .3, .6) return end
  if s == "L" then G.dL = not G.dL else G.dR = not G.dR end
  play("door")
end

local function enterVent()
  if not G.black then return end
  G.mode = "vent"; G.vpos = 0; G.hold = nil; G.cam = false
  play("hatch", .9)
end

local function exitToOffice()
  if G.remy.inOffice then scare("remy") return end
  G.mode = "office"; G.hold = nil; G.camX = 60
  play("hatch", .9)
end

local function exitToPanel()
  if not G.black then return end
  if G.oliver.atPanel then
    if not G.ventWarned then
      -- Оливер ещё у щитка: даём один шанс отползти назад (в первый раз он только шевельнулся)
      G.ventWarned = true
      G.vpos = .72; G.hold = nil; shake = .5
      play("creak", .9, .6); play("heart", 1)
      msg("ОН ЕЩЁ У ЩИТКА! Отползай назад!", 3.5)
      return
    end
    scare("oliver") return
  end
  startPanel()
end

local function pauseGame()
  G.paused = true
  local ret = love.audio.pause()
  G.pauseSrcs = type(ret) == "table" and ret or nil
end

function resumeGame()
  G.paused = false
  if G.pauseSrcs then love.audio.play(G.pauseSrcs) end
  G.pauseSrcs = nil
end

function pauseExitToMenu()
  G.paused = false
  G.pauseSrcs = nil
  CUSTOM = nil
  stopLoops()
  state = "menu"
  menuAmbience()
end

CAM_SIZE_NAMES = {"МАЛЕНЬКИЕ", "СРЕДНИЕ", "БОЛЬШИЕ"}

function pressPause(x, y)
  if hit(x, y, 70, 80, 180, 22) then resumeGame() return end
  if hit(x, y, 70, 108, 180, 22) then
    VOL.camscale = CAM_SIZES[camSizeIndex() % #CAM_SIZES + 1]
    saveVolumes()
    play("beep")
    return
  end
  if hit(x, y, 70, 136, 180, 22) then pauseExitToMenu() return end
end

function pcList()
  local l = {{"remy", "remy"}}
  if G.oliver.on then l[#l + 1] = {"oliver", "oliver"} end
  if G.wat.on then l[#l + 1] = {"archie", "archie"} end
  if G.run.on then l[#l + 1] = {"jack", "jack"} end
  return l
end

function openPC()
  if G.black then msg(L("msg_no_power"), 2) return end
  G.mode = "pc"; G.hold = nil; G.pcRepT = nil
  play("beep")
end

function closePC()
  G.mode = "office"; G.pcRepT = nil; play("beep")
  if G.remy.inOffice then scare("remy") end
end

function pressPC(x, y)
  -- закрыть: красный крестик окна или вкладка «Закрыть» на панели задач
  if hit(x, y, 282, 28, 32, 20) or hit(x, y, 56, 160, 84, 20) then closePC() return end
  if hit(x, y, 58, 47, 250, 24) then
    if brokenCount() > 0 and not G.pcRepT then G.pcRepT = 4; play("repair", .6) end
    return
  end
  if hit(x, y, 58, 134, 250, 20) then
    if G.reserve then msg("Резервный заряд уже использован.", 2)
    elseif G.power >= 90 then msg("Заряд ещё достаточный.", 2)
    else
      G.reserve = true; G.power = math.min(100, G.power + 12)
      play("restore", .5); msg("Резервный заряд: +12% питания.", 2.5)
    end
    return
  end
  if night < 4 then return end
  for i, e in ipairs(pcList()) do
    local bx, by = 64 + ((i - 1) % 2) * 122, 78 + floor((i - 1) / 2) * 21
    if hit(x, y, bx - 2, by - 2, 122, 22) then
      local k = e[1]
      if G.off[k] > 0 then return end
      local cnt = 0
      for _, v in pairs(G.off) do if v > 0 then cnt = cnt + 1 end end
      local maxn = (night >= 5) and 2 or 1
      if cnt >= maxn then msg("Одновременно можно отключить: " .. maxn, 2) return end
      if G.pcCd > 0 and cnt == 0 then msg("Система перезаряжается: " .. math.ceil(G.pcCd) .. " с", 2) return end
      G.off[k] = 10
      if cnt == 0 then G.pcCd = 35 end
      play("click"); play("zap", .4)
      return
    end
  end
end

-- кнопка в стиле Windows XP (Luna): светлая, с голубой рамкой и бликом
function xpBtn(x, y, w, h, label, active, sz)
  lg.setColor(0, .15, .5, 1)
  lg.rectangle("fill", x, y, w, h, 3, 3)
  if active then lg.setColor(.8, .94, .8, 1) else lg.setColor(.97, .97, .95, 1) end
  lg.rectangle("fill", x + 1, y + 1, w - 2, h - 2, 2, 2)
  lg.setColor(1, 1, 1, .6)
  lg.rectangle("fill", x + 2, y + 2, w - 4, math.floor((h - 4) / 2), 2, 2)
  lg.setColor(active and .55 or .93, active and .85 or .85, active and .55 or .7, .9)   -- нижний тёплый край кнопки
  lg.rectangle("fill", x + 2, y + h - 4, w - 4, 2)
  T(label, x, y + (h - 8) / 2, w, active and {.05, .35, .05} or {0, 0, 0}, sz or 7)
end

