local function pressGame(x, y)
  if G.paused then pressPause(x, y) return end
  if G.intro > 0 or G.out then return end
  if hit(x, y, 68, 0, 42, 17) then pauseGame() play("beep") return end
  if G.call and not G.mute and hit(x, y, 254, 30, 60, 12) then
    G.mute = true; G.call = nil
    if G.voice then G.voice:stop(); G.voice = nil end
    if G.ringSrc then G.ringSrc:stop(); G.ringSrc = nil end
    G.ringT = nil
    play("hangup")
    return
  end

  if G.mode == "pc" then pressPC(x, y) return end

  if G.mode == "vent" and not G.cam then
    if hit(x, y, 100, 118, 120, 30) then openCam()
    elseif hit(x, y, 8, 150, 100, 24) then G.hold = "vl"
    elseif hit(x, y, 212, 150, 100, 24) then G.hold = "vr"
    elseif hit(x, y, 112, 150, 96, 24) then
      if G.vpos <= .03 then exitToOffice() elseif G.vpos >= .97 then exitToPanel() end
    end
    return
  end

  if G.mode == "panel" and not G.cam then
    if hit(x, y, 8, 150, 96, 24) then
      G.mode = "vent"; G.vpos = 1; G.hold = nil; play("hatch", .9)
    elseif G.pz and G.pz.ready and not G.pz.done and hit(x, y, 112, 150, 96, 24) then
      G.hold = "lever"
    else
      for i = 1, 3 do
        if hit(x, y, 56 + (i - 1) * 70 - 8, 38, 66, 72) then tapBreaker(i) return end
      end
    end
    return
  end

  if G.cam then
    if hit(x, y, 108, 152, 104, 28) then closeCam() return end
    if G.camLock then return end
    -- ближайшая к пальцу камера (в пределах 6 px), чтобы всегда попадать по нужной кнопке
    local bestId, bestD = nil, 6
    for id = 1, 8 do
      local bx, by, bw, bh = camRect(id)
      local dx = max(bx - x, 0, x - (bx + bw))
      local dy = max(by - y, 0, y - (by + bh))
      local d = math.sqrt(dx * dx + dy * dy)
      if d < bestD then bestId, bestD = id, d end
    end
    if bestId then
      local id = bestId
      if G.sel ~= id then G.sel = id; G.camT = .25; G.hold = nil; G.repairP = 0; play("cam") end
      return
    end
    if hit(x, y, 2, 150, 106, 22) then
      if G.broken[G.sel] then G.hold = "repair"
      elseif G.sel == 5 and boxOn() then G.hold = "wind"
      elseif G.sel == 6 then doZap() end
      return
    end
    return
  end

  if hit(x, y, 84, 152, 152, 28) then openCam() return end
  if hit(x, y, 0, 64, 22, 48) then G.hold = "scrL" return end
  if hit(x, y, 298, 64, 22, 48) then G.hold = "scrR" return end
  local wx = x + G.camX
  -- берём ближайшую к пальцу кнопку (до 8 px от неё), чтобы игрок всегда попадал в нужную
  local function dist(rx, ry, rw, rh)
    local dx = max(rx - wx, 0, wx - (rx + rw))
    local dy = max(ry - y, 0, y - (ry + rh))
    return math.sqrt(dx * dx + dy * dy)
  end
  local cands = {
    {dist(PNL.L + 4, 64, 28, 20), function() toggleDoor("L") end},
    {dist(PNL.L + 4, 86, 28, 20), function() setLight("L") end},
    {dist(PNL.R + 4, 64, 28, 20), function() toggleDoor("R") end},
    {dist(PNL.R + 4, 86, 28, 20), function() setLight("R") end},
    {dist(WBTN.x, WBTN.y, 28, 24), function() setLight("W") end},
    {dist(VENT.x - 4, VENT.y - 4, VENT.w + 8, VENT.h + 8), function() enterVent() end},
    {dist(190, 134, 48, 18), function() G.pcTap = G.camX; G.drag = true end},  -- ПК откроется при отпускании, если не было сдвига
  }
  local best, bd = nil, 8
  for _, c in ipairs(cands) do if c[1] < bd then best, bd = c, c[1] end end
  if best then best[2]() else G.drag = true end
end

