function pressGallery(x, y)
  if gallery.scare then return end
  if hit(x, y, 8, 156, 60, 18) then state = "menu"; play("tablet", .4, .7); return end
  if hit(x, y, 80, 156, 70, 18) then
    local idx = 1
    for i, n in ipairs(GAL_CHARS) do if n == gallery.who then idx = i end end
    gallery.who = GAL_CHARS[idx % #GAL_CHARS + 1]
    play("beep"); return
  end
  if hit(x, y, 160, 156, 70, 18) then
    gallery.scare = true; gallery.t = 0; playScare(gallery.who); return
  end
  if hit(x, y, 240, 156, 36, 18) then
    gallery.room = gallery.room % GAL_ROOMS + 1; play("cam"); return
  end
  if hit(x, y, 280, 156, 36, 18) then
    gallery.room = (gallery.room - 2) % GAL_ROOMS + 1; play("cam"); return
  end
end

function drawGallery()
  if gallery.scare then
    R(0, 0, W, H, {0, 0, 0})
    local t = gallery.t
    local s = min(6.6, 2.5 + t * 22) + sin(t * 60) * .15
    if floor(t * 30) % 2 == 0 then R(0, 0, W, H, {.25, 0, 0}) end
    local name = gallery.who
    if IMG_SPRITES[name] then
      local im = SPR[name]
      local w, h = im:getDimensions()
      local scale = s * (78 / h) * 2.4
      local oy = (name == "oliver") and h * .28 or (HEADLESS[name] and h * scareEY(name) or h * .18)
      local yOff = (name == "oliver") and 110 or (HEADLESS[name] and 74 or 110)  -- Оливер чуть пониже
      lg.setColor(1, 1, 1)
      lg.draw(im, 160 + rnd(-4, 4), yOff + rnd(-4, 4), 0, scale, scale, scareAX(name, w), oy)
    else
      spr(name, 160 + rnd(-5, 5), 92 + rnd(-5, 5), s)
    end
    static(300, .6)
    return
  end
  local c = gallery.room
  lg.setColor(.75, 1, .8)
  if c <= 8 then lg.draw(BG.cam[c], 0, 0)
  elseif BG.office then lg.draw(BG.office, c == 9 and -144 or 0, 0)  -- окно (прокручено вправо) и левая дверь
  else R(0, 0, W, H, {.04, .04, .05}) end
  local who = gallery.who
  local spot = GAL_POS[who] and GAL_POS[who][c]
  if c == 9 then
    if who == "archie" then
      local sx = WIN.x - 144
      lg.setScissor(sx, WIN.y, WIN.w, WIN.h)
      lg.push(); lg.translate(sx, WIN.y); lg.scale(WIN.w / 64, WIN.w / 64)
      placeFigure("archie", 32, 70, 64, .9)
      lg.pop()
      drawWinBars(sx)
      lg.setScissor()
    else T("нет", 0, 80, W, {.6, .6, .6}, 8) end
  elseif spot then placeFigure(who, spot[1], spot[2], spot[3], spot[4])
  else T("нет", 0, 80, W, {.6, .6, .6}, 8) end
  T(GAL_NAMES[who], 8, 4, 120, {1, 1, 1}, 8, nil, "left")
  T(GAL_ROOM_NAMES[c] or ("К" .. c), 130, 4, 60, {.8, .8, .8}, 8)
  R(8, 156, 60, 18, {.1, .1, .1}, .8); T("НАЗАД", 8, 160, 60, {1, 1, 1}, 7)
  R(80, 156, 70, 18, {.1, .1, .1}, .8); T("СМЕНА", 80, 160, 70, {1, 1, 1}, 7)
  R(160, 156, 70, 18, {.3, .05, .05}, .8); T("СКРИМЕР", 160, 160, 70, {1, .6, .6}, 7)
  R(240, 156, 36, 18, {.1, .1, .1}, .8); T(">", 240, 160, 36, {1, 1, 1}, 8)
  R(280, 156, 36, 18, {.1, .1, .1}, .8); T("<", 280, 160, 36, {1, 1, 1}, 8)
  scanlines()
end

local function menuLayout()
  if customUnlocked then
    if maxNight > 1 then return {new = 74, cont = 92, cust = 114, set = 132, exit = 150, sel = 166} end
    return {new = 80, cust = 102, set = 124, exit = 146, sel = 164}
  end
  if maxNight > 1 then return {new = 74, cont = 94, set = 120, exit = 140, sel = 160} end
  return {new = 90, set = 112, exit = 134, sel = 156}
end

local function pressMenu(x, y)
  local ML = menuLayout()
  -- секрет: 5 быстрых нажатий на название открывают/прячут выбор ночи
  if hit(x, y, 10, 6, 104, 54) then
    if clock - titleTapT > 1.2 then titleTaps = 0 end
    titleTapT = clock; titleTaps = titleTaps + 1
    if titleTaps >= 5 then
      titleTaps = 0; nightReveal = not nightReveal; play("beep", 1, 1.6)
    end
    return
  end
  -- секрет: 5 быстрых нажатий на подзаголовок открывают «Свою ночь»
  if hit(x, y, 10, 62, 200, 10) then
    if clock - subTapT > 1.2 then subTaps = 0 end
    subTapT = clock; subTaps = subTaps + 1
    if subTaps >= 5 then subTaps = 0; state = "custom"; play("beep", 1, .7) end
    return
  end
  CUSTOM = nil
  if hit(x, y, 6, ML.new - 2, 190, 22) then
    menuSel = 1
    if maxNight > 1 and not (MENU_CONF and clock - MENU_CONF < 4) then MENU_CONF = clock; play("beep"); return end
    MENU_CONF = nil
    night = nearestAvailableNight(1); maxNight = night; selNight = night
    love.filesystem.write("save.txt", tostring(maxNight)); love.filesystem.write("save.bak", tostring(maxNight))
    if night == 1 then startPrologue() else startNight() end
  elseif maxNight > 1 and hit(x, y, 6, ML.cont - 2, 190, customUnlocked and 20 or 30) then
    menuSel = 2
    night = nearestAvailableNight(maxNight); startNight()
  elseif customUnlocked and hit(x, y, 6, ML.cust - 2, 190, 22) then
    menuSel = 6; state = "custom"; play("beep", 1, .8)
  elseif hit(x, y, 6, ML.set - 2, 190, 22) then
    menuSel = 4
    state = "settings"
    settings.mode = "cats"
    settings.scroll = 0
    settings.cat = nil
    stopLoops()
  elseif hit(x, y, 6, ML.exit - 2, 190, 22) then
    menuSel = 5
    love.event.quit()
  elseif nightReveal and hit(x, y, 6, ML.sel - 4, 26, 22) then
    menuSel = 3
    for n = selNight - 1, 1, -1 do if isNightAvailable(n) then selNight = n; break end end
    play("beep")
  elseif nightReveal and hit(x, y, 170, ML.sel - 4, 26, 22) then
    menuSel = 3
    for n = selNight + 1, 6 do if isNightAvailable(n) then selNight = n; break end end
    play("beep")
  elseif nightReveal and hit(x, y, 34, ML.sel - 4, 134, 22) then
    menuSel = 3
    if isNightAvailable(selNight) then night = selNight; nightReveal = false; startNight() end
  elseif hit(x, y, 292, 0, 28, 18) then
    -- скрытая кнопка: невидимый угол в правом верхнем углу открывает проверку скримеров
    gallery = {who = "remy", room = 1, scare = false, t = 0}
    state = "gallery"
    play("beep")
  end
end

---------------------------------------------------------------- своя ночь (скрытая)
CN_KEYS = {"remy", "oliver", "archie", "jack", "melody"}
CN_NAMES = {remy = "РЕМИ", oliver = "ОЛИВЕР", archie = "АРЧИ", jack = "ДЖЕК", melody = "МЕЛОДИ"}
CN_LV = {remy = 10, oliver = 10, archie = 10, jack = 10, melody = 10}

function saveCustom()
  local t = {}
  for i, k in ipairs(CN_KEYS) do t[i] = tostring(CN_LV[k]) end
  love.filesystem.write("custom.txt", table.concat(t, ","))
end

function loadCustom()
  local data = love.filesystem.read("custom.txt")
  if not data then return end
  local i = 0
  for v in data:gmatch("%d+") do
    i = i + 1
    local k = CN_KEYS[i]
    if k then CN_LV[k] = max(0, min(20, tonumber(v) or 10)) end
  end
end

function drawCustom()
  R(0, 0, W, H, {.012, .004, .016})
  static(220, .12)
  T("СВОЯ НОЧЬ", 0, 4, W, WHITE, 12)
  R(110, 19, 100, 1, {.5, .05, .08})
  T("УРОВЕНЬ ИИ: 0 — СТОИТ НА МЕСТЕ, 20 — МАКСИМУМ", 0, 22, W, {.5, .5, .5}, 5)
  local total = 0
  for i, k in ipairs(CN_KEYS) do
    local cx = 12 + (i - 1) * 60
    local lv = CN_LV[k]
    total = total + lv
    local f = lv / 20
    -- рамка: серая при 0, краснеет с ростом уровня
    R(cx - 2, 30, 60, 54, {.25 + .5 * f, .25 - .17 * f, .27 - .19 * f})
    R(cx, 32, 56, 50, {.03, .01, .02})
    local b = .6 + .35 * f
    if IMG_SPRITES[k] then
      local im = SPR[k]
      local iw, ih = im:getDimensions()
      local ex, ey = (EYE[k] or {.5, .2})[1], (EYE[k] or {.5, .2})[2]
      local cH = ih * .42
      local cW = cH * 56 / 50
      local x0 = max(0, min(iw - cW, ex * iw - cW / 2))
      local y0 = max(0, ey * ih - cH * .4)
      lg.setColor(b, b * (1 - .45 * f), b * (1 - .45 * f), 1)
      lg.draw(im, lg.newQuad(x0, y0, cW, cH, iw, ih), cx, 32, 0, 56 / cW, 50 / cH)
    else
      spr(k, cx + 28, 57, 1.1, {b, b * .6, b * .6})
    end
    R(cx, 32, 56, 50, {.6, 0, 0}, .1 * f)
    T(CN_NAMES[k], cx, 85, 56, {.95, .95, .95}, 6)
    local c = lv == 0 and {.45, .45, .45} or (lv >= 15 and {1, .3, .3} or (lv >= 10 and {1, .65, .25} or {.92, .92, .92}))
    T(tostring(lv), cx, 94, 56, c, 14)
    R(cx, 111, 56, 3, {.1, .08, .1})
    R(cx, 111, floor(56 * f), 3, {.4 + .6 * f, .5 - .35 * f, .1})
    btn(cx, 118, 26, 18, "<", nil, nil, 10)
    btn(cx + 30, 118, 26, 18, ">", nil, nil, 10)
  end
  T("СУММА УРОВНЕЙ: " .. total .. " / 100", 0, 140, W, total >= 80 and {1, .35, .35} or {.6, .6, .6}, 5.5)
  btn(8, 152, 56, 22, "НАЗАД")
  btn(70, 152, 50, 22, "ВСЕ 0")
  btn(126, 152, 50, 22, "ВСЕ 20")
  btn(182, 152, 46, 22, "ЧЕЛЛЕНДЖИ", nil, nil, 5)
  btn(232, 152, 80, 22, "ПУСК", {.25, .08, .08})
  scanlines()
end

function pressCustom(x, y)
  for i, k in ipairs(CN_KEYS) do
    local cx = 12 + (i - 1) * 60
    if hit(x, y, cx - 2, 112, 30, 26) then CN_LV[k] = max(0, CN_LV[k] - 1); play("beep", .6) return end
    if hit(x, y, cx + 28, 112, 30, 26) then CN_LV[k] = min(20, CN_LV[k] + 1); play("beep", .6) return end
    -- нажатие на портрет: сразу 20, а если уже 20 — обнуляет
    if hit(x, y, cx - 2, 30, 60, 54) then CN_LV[k] = (CN_LV[k] < 20) and 20 or 0; play("beep", .8, 1.2) return end
  end
  if hit(x, y, 8, 152, 56, 22) then saveCustom(); state = "menu"; play("beep") return end
  if hit(x, y, 70, 152, 50, 22) then for _, k in ipairs(CN_KEYS) do CN_LV[k] = 0 end play("beep") return end
  if hit(x, y, 126, 152, 50, 22) then for _, k in ipairs(CN_KEYS) do CN_LV[k] = 20 end play("beep") return end
  if hit(x, y, 180, 152, 50, 22) then state = "challenges"; play("beep", 1, .9) return end
  if hit(x, y, 232, 152, 80, 22) then
    saveCustom()
    CUSTOM = {}
    for k, v in pairs(CN_LV) do CUSTOM[k] = v end
    night = 6
    startNight()
  end
end

