function chCard(i)
  local col, row = (i - 1) % 2, floor((i - 1) / 2)
  return 8 + col * 156, 28 + row * 42, 152, 38
end

function drawChallenges()
  R(0, 0, W, H, {.012, .004, .016})
  static(220, .12)
  T("ЧЕЛЛЕНДЖИ", 0, 4, W, WHITE, 12)
  R(110, 19, 100, 1, {.5, .05, .08})
  for i, c in ipairs(CN_CHALLENGES) do
    local x, y, w, h = chCard(i)
    local done = CN_DONE[c.id]
    R(x - 1, y - 1, w + 2, h + 2, done and {.15, .5, .2} or {.45, .12, .15})
    R(x, y, w, h, {.05, .03, .05})
    T(c.name, x + 6, y + 4, w - 12, {.95, .95, .95}, 7, nil, "left")
    T(c.desc, x + 6, y + 16, w - 12, {.6, .6, .65}, 4.5, nil, "left")
    local parts = {}
    for _, k in ipairs(CN_KEYS) do parts[#parts + 1] = CH_SHORT[k] .. c.lv[k] end
    T(table.concat(parts, " "), x + 6, y + 27, w - 12, {.85, .6, .35}, 4.5, nil, "left")
    if done then T("ПРОЙДЕН", x + w - 56, y + 4, 52, {.4, 1, .5}, 4.5, nil, "right") end
  end
  btn(8, 158, 56, 18, "НАЗАД")
  T("Нажми на челлендж, чтобы начать", 70, 163, 180, {.45, .45, .5}, 5)
  scanlines()
end

function pressChallenges(x, y)
  if hit(x, y, 8, 156, 56, 22) then state = "custom"; play("beep") return end
  for i, c in ipairs(CN_CHALLENGES) do
    local cx, cy, cw, ch = chCard(i)
    if hit(x, y, cx, cy, cw, ch) then
      CUSTOM = {challenge = c.id, challengeName = c.name}
      for k, v in pairs(c.lv) do CUSTOM[k] = v end
      night = 6
      startNight()
      return
    end
  end
end

