function startArchive()
  ARCHIVE.view = "desk"; ARCHIVE.doc = 1; ARCHIVE.page = 1
  ARCHIVE.read = {false, false}; ARCHIVE.t = 0; ARCHIVE.phase = "archive"; ARCHIVE.hint = 0
  state = "archive"
  stopLoops()
  S.hum:setVolume(.1 * getVol("hum")); S.hum:play()
end

function finishArchive()
  archiveOk = true
  startNight()
end

local function archiveReady() return ARCHIVE.read[1] and ARCHIVE.read[2] end

function pressArchive(x, y)
  local A = ARCHIVE
  if A.phase == "transition" then
    if A.t > 1.5 then finishArchive() end
    return
  end
  if A.view == "desk" then
    if hit(x, y, 22, 54, 122, 88) then A.view = "doc"; A.doc = 1; A.page = 1; play("click"); return end
    if hit(x, y, 176, 54, 122, 88) then A.view = "doc"; A.doc = 2; A.page = 1; play("click"); return end
    if hit(x, y, 100, 150, 120, 26) then
      if archiveReady() then
        A.phase = "transition"; A.t = 0; play("beep", 1, .8)
      else
        A.hint = 2.5; play("beep", .5, .6)
      end
    end
  else
    local d = ARCHIVE_DOCS[A.doc]
    if hit(x, y, 232, 152, 62, 24) then A.view = "desk"; play("click"); return end
    if hit(x, y, 26, 152, 64, 24) or hit(x, y, 26, 10, 90, 134) then
      if A.page > 1 then A.page = A.page - 1; play("click", .6) end
      return
    end
    if hit(x, y, 96, 152, 64, 24) or hit(x, y, 204, 10, 90, 134) then
      if A.page < #d.pages then A.page = A.page + 1; play("click", .6) end
      if A.page == #d.pages then A.read[A.doc] = true end
      return
    end
  end
end

