    R(150, 6, 28, 8, {.85, .8, .6}, .55)                              -- скотч
    T(d.title, 34, 16, 252, {.4, .05, .05}, 5.5, nil, "left")
    T(pg.head, 34, 27, 252, {.15, .1, .07}, 5.5, nil, "left")
    T(pg.body, 34, 40, 252, {.17, .12, .08}, 5.2, nil, "left")
    T("стр. " .. A.page .. " из " .. #d.pages, 214, 135, 74, {.35, .28, .2}, 4.5, nil, "right")
    if A.page == 1 then
      lg.setColor(.7, .08, .08, .75); lg.rectangle("line", 226, 16, 62, 14)
      T("СЕКРЕТНО", 226, 20, 62, {.7, .08, .08}, 5.5)
    end
    btn(26, 152, 64, 24, "< ПРЕД.", nil, A.page > 1 and WHITE or {.4, .4, .4}, 6)
    btn(96, 152, 64, 24, "СЛЕД. >", nil, A.page < #d.pages and WHITE or {.4, .4, .4}, 6)
    btn(232, 152, 62, 24, "ЗАКРЫТЬ", nil, nil, 6)
  end
  if A.hint > 0 then A.hint = A.hint - 1 / 60 end
  static(160, .1)
  vignette(.4)
  scanlines()
end

function startPrologue()
  PRO.imgs = {}
  for n = 1, 12 do
    for _, pth in ipairs({"prologue/prologue image " .. n .. ".png", "prologue image " .. n .. ".png", "prologue/prologue_image_" .. n .. ".png"}) do
      if love.filesystem.getInfo(pth) then
        local ok, im = pcall(lg.newImage, pth)
        if ok and im then im:setFilter("linear", "linear"); PRO.imgs[#PRO.imgs + 1] = im; break end
      end
    end
  end
  if #PRO.imgs == 0 then startNight() return end
  PRO.i = 1; PRO.t = 0
  stopLoops()
  S.hum:setVolume(.12 * getVol("hum")); S.hum:play()
  state = "prologue"
end

function drawPrologue()
  R(0, 0, W, H, {0, 0, 0})
  local im = PRO.imgs[PRO.i]
  if im then
    local iw, ih = im:getDimensions()
    local sc = math.min(W / iw, H / ih)
    lg.setColor(1, 1, 1, math.min(1, PRO.t / 1.0))
    lg.draw(im, W / 2, H / 2, 0, sc, sc, iw / 2, ih / 2)
  end
end

local function press(x, y)
  if state == "menu" then
    pressMenu(x, y)
  elseif state == "custom" then
    pressCustom(x, y)
  elseif state == "challenges" then
    pressChallenges(x, y)
  elseif state == "gallery" then
    pressGallery(x, y)
  elseif state == "settings" then
    pressSettings(x, y)
  elseif state == "over" then
    if over.t > 1.5 then
      if hit(x, y, 220, 132, 92, 24) then pauseExitToMenu() else startNight() end
    end
  elseif state == "win" then
    if winT > 4.5 then
      if story.pages and #story.pages > 0 then state = "story"; story.i = 1 else afterWin() end
    end
  elseif state == "prologue" then
    if PRO.t > .8 then
      PRO.i = PRO.i + 1; PRO.t = 0
      if PRO.i > #PRO.imgs then startNight() end
    end
  elseif state == "archive" then
    pressArchive(x, y)
  elseif state == "story" then
    story.i = story.i + 1
    if story.i > #story.pages then afterWin() end
  elseif state == "game" then
    pressGame(x, y)
  end
end

local lastPress = {t = -1, x = -99, y = -99}
function love.mousepressed(px, py)
  -- защита от дубля касания (touch + mouse приходят вместе) — из-за него кнопки срабатывали через раз
  local now = love.timer.getTime()
  if now - lastPress.t < .08 and math.abs(px - lastPress.x) < 6 and math.abs(py - lastPress.y) < 6 then return end
  lastPress.t, lastPress.x, lastPress.y = now, px, py
  press((px - ox) / scale, (py - oy) / scale)
end

function love.mousereleased()
  if G and state == "game" and G.pcTap and G.mode == "office" and not G.cam and math.abs(G.camX - G.pcTap) < 3 then
    G.pcTap = nil
    openPC()
  end
  if G then G.pcTap = nil; G.hold = nil; G.drag = false end
  if settings then settings.drag = false end
end

function love.mousemoved(_, _, dx)
  if state == "game" and G and G.drag and G.mode == "office" and not G.cam then
    G.camX = max(0, min(OW - W, G.camX - dx / scale))
  elseif state == "settings" and settings.drag then
    local dy = (love.mouse.getY() - oy) / scale - settings.lastY
    if math.abs(dy) > 8 then
      local dir = dy > 0 and -1 or 1
      local maxScroll = 0
      if settings.mode == "cats" then
        maxScroll = max(0, #CATEGORIES - 8)
      elseif settings.cat then
        maxScroll = max(0, #settings.cat.items - 8)
      end
      settings.scroll = max(0, min(maxScroll, settings.scroll + dir))
      settings.lastY = (love.mouse.getY() - oy) / scale
    end
  end
end

---------------------------------------------------------------- отрисовка
CRACKS = {{10, 0, 14, 18}, {14, 18, 6, 34}, {14, 18, 24, 30}, {24, 30, 22, 46}, {40, 0, 36, 14},
                {36, 14, 46, 28}, {46, 28, 40, 44}, {50, 66, 44, 52}, {20, 66, 26, 50}}

function drawDoorSide(wx, p, lit, name, cx, jk)
  local sx = wx - cx
  lg.setScissor(sx, 32, 64, 102)
  if lit then
    local left = (wx == DX.L)
    local c1 = left and {.62, .56, .3} or {.35, .5, .62}
    R(sx, 32, 64, 102, {.03, .03, .04})
    lg.setColor(c1[1] * .5, c1[2] * .5, c1[3] * .5, 1); lg.polygon("fill", sx, 32, sx + 22, 62, sx + 22, 104, sx, 134)
    lg.setColor(c1[1] * .4, c1[2] * .4, c1[3] * .4, 1); lg.polygon("fill", sx + 64, 32, sx + 42, 62, sx + 42, 104, sx + 64, 134)
    lg.setColor(c1[1] * .25, c1[2] * .25, c1[3] * .25, 1); lg.polygon("fill", sx, 32, sx + 64, 32, sx + 42, 62, sx + 22, 62)
    lg.setColor(c1[1] * .65, c1[2] * .65, c1[3] * .65, 1); lg.polygon("fill", sx, 134, sx + 64, 134, sx + 42, 104, sx + 22, 104)
    lg.setColor(0, 0, 0, .4)
    for i = -3, 3 do lg.line(sx + 32 + i * 5, 104, sx + 32 + i * 22, 134) end
    for k = 1, 4 do
      local y = 104 + 30 * (k / 4) ^ 2
      local t = (y - 104) / 30
      lg.line(sx + 22 - 22 * t, y, sx + 42 + 22 * t, y)
    end
    R(sx + 22, 62, 20, 42, {.01, .01, .02})
    R(sx + 26, 74, 12, 18, c1, .1)
    R(sx + 22, 45, 20, 2, {1, .92, .65}, .7)
    R(sx, 32, 64, 102, c1, .05 + .05 * rnd())
  end
  if jk and lit then
    -- Джек бежит по коридору: при свете виден, всё крупнее по мере приближения
    placeFigure("jack", sx + 32, 98 + 34 * jk, 22 + 80 * jk, .5 + .5 * jk)
  end
  if name and p < .7 then
    if lit then
      placeFigure(name, sx + 32, 132, 98, 1)
    else
      lg.setColor(1, 1, 1, .15 + .35 * rnd())
      lg.rectangle("fill", sx + 22, 80, 4, 3)
      lg.rectangle("fill", sx + 38, 80, 4, 3)
    end
  end
  if p > 0 then
    local h = floor(102 * p)
    R(sx, 32, 64, h, {.24, .26, .3})
    for i = 0, h - 4, 8 do R(sx, 32 + i, 64, 2, {.14, .15, .18}) end
    R(sx, 32 + h - 3, 64, 3, {.55, .5, .15})
  end
  lg.setScissor()
  if lit and not (name and p < .7) then R(sx - 8, 136, 80, 18, {1, .9, .5}, .08) end
end

function drawWindow(cx)
  local sx = WIN.x - cx
  local k = WIN.w / 64
  local w = G.wat
  lg.setScissor(sx, WIN.y, WIN.w, WIN.h)
  local on = G.lW and not G.black
  if on then R(sx, WIN.y, WIN.w, WIN.h, {.55, .6, .7}, .35 + .05 * rnd()) end
  if w.on and w.ws >= 2 then
    lg.push()
    lg.translate(sx, WIN.y)
    lg.scale(k, k)
    if IMG_SPRITES.archie then
      -- в окно смотрит крупное лицо Арчи (кадр вокруг глаз), а не уменьшенная фигура целиком
      local k2 = on and 1 or .25
      local im = SPR.archie
      local iw, ih = im:getDimensions()
      local ex, ey = (EYE.archie or {.608, .185})[1], (EYE.archie or {.608, .185})[2]
      local zoom = (w.ws == 3) and .30 or .36   -- у самого окна лицо ещё крупнее
      local cH = ih * zoom
      local cW = cH * 64 / 66
      local x0 = max(0, min(iw - cW, ex * iw - cW / 2))
      local y0 = max(0, ey * ih - cH * .42)
      lg.setColor(k2, k2, k2, 1)
      lg.draw(im, lg.newQuad(x0, y0, cW, cH, iw, ih), 0, 0, 0, 64 / cW, 66 / cH)
      if not on then
        local exl = (ex * iw - x0) / cW * 64
        local eyl = (ey * ih - y0) / cH * 66
        R(exl - 10, eyl - 1, 5, 3, {.7, .3, 1}, .5 + .4 * rnd())
        R(exl + 5, eyl - 1, 5, 3, {.7, .3, 1}, .5 + .4 * rnd())
      end
    elseif on then
      spr("archie", 32, 34, 1.5)
    else
      spr("archie", 32, 34, 1.5, {0, 0, 0}, .9)
      R(20, 30, 4, 3, {.9, .85, .3}, .4 + .4 * rnd())
      R(40, 30, 4, 3, {.9, .85, .3}, .4 + .4 * rnd())
    end
    if w.ws == 3 then
      local prog = 1 - w.T / max(.1, w.Tmax)
      local n = floor(prog * #CRACKS) + 1
      lg.setColor(1, 1, 1, .85)
      for i = 1, min(n, #CRACKS) do
        local c = CRACKS[i]
        lg.line(c[1], c[2], c[3], c[4])
      end
    end
    lg.pop()
    drawWinBars(sx)
  end
  lg.setScissor()
end

function drawPanels(cx)
  for _, s in ipairs({"L", "R"}) do
    local sx = PNL[s] + 4 - cx
    local closed = (s == "L") and G.dL or G.dR
    local heat = (s == "L") and G.hL or G.hR
    local lock = (s == "L") and G.kL or G.kR
    local lit = (s == "L") and G.lL or G.lR
    if lock then
      btn(sx, 64, 28, 20, L("btn_hot"), {.7, .35, 0}, nil, 6)
    else
      btn(sx, 64, 28, 20, L("btn_door"), closed and {.75, .1, .1} or nil)
    end
    btn(sx, 86, 28, 20, L("btn_light"), (lit and not G.black) and {.8, .7, .1} or nil, lit and {0, 0, 0} or nil)
    R(sx, 110, 28, 5, {.1, .1, .1})
    R(sx, 110, floor(28 * heat / 100), 5,
      heat >= 80 and {.95, .1, .1} or (heat >= 50 and {.95, .65, .1} or {.3, .8, .3}))
  end
  btn(WBTN.x - cx, WBTN.y, 28, 24, L("btn_window"), (G.lW and not G.black) and {.8, .7, .1} or nil, G.lW and {0, 0, 0} or nil)
end

-- затемнение по краям кадра
function vignette(k)
  for i = 0, 9 do
    local al = k * (10 - i) / 10
    R(i * 3, 0, 3, H, {0, 0, 0}, al); R(W - i * 3 - 3, 0, 3, H, {0, 0, 0}, al)
    R(0, i * 3, W, 3, {0, 0, 0}, al * .8); R(0, H - i * 3 - 3, W, 3, {0, 0, 0}, al * .8)
  end
end
-- таймкод записи камер: идёт вместе с ночным временем
function camStamp()
  local hl = NIGHT_LEN / 6
  local hr = floor(G.time / hl)
  local mn = floor((G.time % hl) / hl * 60)
  return string.format("%02d:%02d:%02d", hr == 0 and 12 or hr, mn, floor(clock * 7) % 60)
end

local function drawOffice()
  local cx = floor(G.camX)
  lg.setColor(1, 1, 1)
  lg.draw(BG.office, -cx, 0)
  local g = G.remy
  local atL = (g.pos == 3 and g.side == "L" and not g.inOffice) and "remy" or nil
  local atR = (g.pos == 3 and g.side == "R" and not g.inOffice) and "remy" or nil
  if not atR and G.oliver.on and G.oliver.pos == 3 and G.oliver.route == "door" then atR = "oliver" end
  drawDoorSide(DX.L, G.pL, G.lL, atL, cx, (G.run.on and G.run.rs == 3) and (1 - G.run.rp) or nil)
  drawDoorSide(DX.R, G.pR, G.lR, atR, cx)
  drawWindow(cx)
  -- вентилятор: настольный, в защитной решётке, с покачиванием и лентой на потоке воздуха
  local sway = G.black and 0 or sin(clock * .6) * 1.5
  local fx, fy = 160 - cx + sway, 112
  R(160 - cx - 8, 122, 16, 3, {.16, .16, .19}); R(160 - cx - 8, 122, 16, 1, {.3, .3, .34})
  R(160 - cx - 1, fy + 5, 3, 17, {.22, .22, .25})
  R(fx - 4, fy - 3, 8, 10, {.12, .12, .15})                                  -- корпус мотора
  local spin = G.black and 0 or clock * 22
  for i = 0, 2 do
    local a1 = spin + i * pi * 2 / 3
    lg.setColor(.55, .58, .66, .95)
    lg.polygon("fill", fx, fy, fx + cos(a1 - .38) * 10, fy + sin(a1 - .38) * 10, fx + cos(a1 + .38) * 10, fy + sin(a1 + .38) * 10)
    if not G.black then
      lg.setColor(.55, .58, .66, .22)
      local a2 = a1 - .5
      lg.polygon("fill", fx, fy, fx + cos(a2 - .38) * 10, fy + sin(a2 - .38) * 10, fx + cos(a2 + .38) * 10, fy + sin(a2 + .38) * 10)
    end
  end
  lg.setColor(.3, .3, .35, .95); lg.circle("line", fx, fy, 12); lg.circle("line", fx, fy, 6)
  lg.setColor(.3, .3, .35, .6)
  for i = 0, 7 do lg.line(fx + cos(i * pi / 4) * 2, fy + sin(i * pi / 4) * 2, fx + cos(i * pi / 4) * 12, fy + sin(i * pi / 4) * 12) end
  lg.setColor(.2, .2, .24, 1); lg.circle("fill", fx, fy, 2.5)
  -- красная лента на решётке: колышется, пока вентилятор работает
  if not G.black then
    lg.setColor(.7, .1, .15, .9)
    local ry = fy - 10
    lg.line(fx - 10, ry, fx - 14 + sin(clock * 7) * 2, ry + 3, fx - 18 + sin(clock * 7 + 1) * 3, ry + 5, fx - 21 + sin(clock * 7 + 2) * 3, ry + 4)
  end
  -- монитор: ЭЛТ в пластиковом корпусе с клавиатурой
  local mx = 190 - cx
  local broken = (not G.black) and brokenCount() > 0
  R(mx - 3, 86, 54, 38, {.17, .165, .17}); R(mx - 3, 86, 54, 1, {.34, .33, .35}); R(mx - 3, 123, 54, 1, {.07, .07, .08})
  R(mx + 1, 90, 46, 30, {.02, .025, .025})
  if not G.black then
    local tint = broken and {.28, .06, .06} or {.04, .2, .09}
    R(mx + 2, 91, 44, 28, tint)
    -- строки терминала: бегут вверх
    local shift = floor(clock * 3)
    for i = 0, 6 do
      local w = 10 + ((i + shift) * 7 % 24)
      R(mx + 5, 94 + i * 3.6, w, 1, broken and {.9, .3, .3} or {.2, .85, .4}, .75)
    end
    if floor(clock * 2) % 2 == 0 then R(mx + 5, 94 + 6 * 3.6 + 2, 3, 2, broken and {1, .4, .4} or {.4, 1, .5}) end
    if broken and floor(clock * 3) % 2 == 0 then T("ОШИБКА КАМЕР", mx + 2, 103, 44, {1, .3, .3}, 4) end
    R(mx + 2, 91, 44, 28, {1, 1, 1}, .03)                                  -- блик на стекле
    lg.setColor(broken and 1 or .1, broken and .2 or .8, broken and .15 or .3, .05); lg.circle("fill", mx + 24, 105, 34)
  else
    R(mx + 2, 91, 44, 28, {.015, .02, .02})
  end
  R(mx + 40, 121, 3, 2, (not G.black) and {.2, .9, .3} or {.1, .1, .1})     -- светодиод питания
  R(mx + 34, 87, 10, 9, {.9, .85, .4}); for i = 0, 2 do R(mx + 36, 89 + i * 2.5, 6, 1, {.3, .25, .1}) end  -- стикер
  R(mx + 17, 124, 14, 2, {.1, .1, .12})
  -- клавиатура на столе
  R(mx - 2, 125, 50, 5, {.12, .12, .14}); R(mx - 2, 125, 50, 1, {.24, .24, .27})
  for row = 0, 1 do for k = 0, 10 do R(mx + k * 4.4, 126 + row * 2, 3, 1.3, {.3, .3, .34}) end end
  -- кнопка компьютера на столе (как кнопки двери и света)
  local pcHot = (not G.black) and (brokenCount() > 0)
  btn(mx, 134, 48, 18, "КОМПЬЮТЕР", pcHot and {.55, .35, .05} or nil, nil, 5)
  drawPanels(cx)
  if G.black then
    R(VENT.x - cx - 2, VENT.y - 2, VENT.w + 4, VENT.h + 4, {.4, .7, 1}, .25 + .25 * sin(clock * 5))
  end
  if G.halluc > 0 then
    local kinds = {"remy", "oliver", "archie", "jack", "melody"}
    local dx = (G.hx == 2) and DX.R or DX.L
    local k = (.18 + .3 * rnd()) * min(1, G.halluc / .6 * 3)
    lg.setScissor(dx - cx, 32, 64, 102)
    placeFigure(kinds[G.hk or 1] or "remy", dx - cx + 32, 132, 98, k)
    lg.setScissor()
    if rnd() < .5 then R(0, 0, W, H, {1, 1, 1}, .03) end
  end
  local a = .3 + .1 * min(1, G.time / NIGHT_LEN) + .04 * sin(clock * .6)                       -- тьма «дышит»
  if sin(clock * 13) * sin(clock * 4.7) > .965 then a = a + .14 end  -- лампа иногда моргает
  if not G.black and not G.out then
    -- пылинки в воздухе
    for i = 1, 22 do
      local px = (i * 53 + clock * (3 + i % 4)) % W
      local py = (i * 37 + sin(clock * .4 + i) * 6 + clock * 2) % 150 + 10
      R(px, py, 1, 1, {.9, .85, .7}, .12 + .1 * sin(clock + i))
    end
  end
  if G.flick > 0 then a = a + rnd() * .45 end
  if G.black then a = .62 end
  if G.out then a = .82 end
  R(0, 0, W, H, {0, 0, 0}, a)
  vignette(.28)
  if G.crit ~= nil and not G.black and not G.out then R(0, 0, W, H, {.6, 0, 0}, .04 + .035 * sin(clock * 5)) end
  if not G.black and not G.out then static(30, .06) end
  if G.out and G.outT > 2 and floor(clock * 3) % 4 ~= 0 then
    local sx = DX.L - cx
    lg.setColor(1, 1, 1, .9)
    lg.rectangle("fill", sx + 22, 80, 4, 3)
    lg.rectangle("fill", sx + 38, 80, 4, 3)
  end
end

function camAlert(id)
  if id == 6 and G.oliver.on and G.oliver.pos == 3 and G.oliver.route ~= "door" and not G.black then return "red" end
  if id == 7 and G.run.on and G.run.rs >= 2 then return "red" end
  if id == 7 and G.run.on and G.run.rs == 1 then return "yel" end
  if id == 5 and boxOn() and G.box < 30 then return "yel" end
  if G.warnId == id then return "yel" end
  return nil
end

function drawCamFigures(c)
  local g, d, w, r = G.remy, G.oliver, G.wat, G.run
  if c == 5 and boxOn() then
    if G.box < 35 then
      local e = min(1, (35 - G.box) / 35)  -- 0 = в шкатулке, 1 = вылезла
      if IMG_SPRITES.melody then placeFigure("melody", 160, 200 - e * 82, 90, .8)
      else spr("melody", 160, 92, .8 + e * 1.3, {.7, .7, .7}) end
    end
    R(146, 106, 28, 24, {.45, .25, .4})
    R(144, 102, 32, 5, {.7, .65, .25})
    R(176, 114, 8, 3, {.7, .7, .7}); R(182, 112, 2, 7, {.7, .7, .7})
  elseif c == 5 and not boxOn() then
    -- Мелоди стоит на месте и неактивна до 5-й ночи
    if IMG_SPRITES.melody then placeFigure("melody", 160, 170, 90, .6) else figure("melody", 160, 92, .9, .6) end
  end
  if not g.inOffice and roomCam("remy", g) == c then
    if g.pos == 0 then placeFigure("remy", 90, 168, 128, .9)
    elseif g.pos == 1 then placeFigure("remy", 95, 158, 88, .85)
    else placeFigure("remy", 160, 120, 70, .8) end
  end
  -- Оливер: на сцене стоит справа от Реми, левее плана камер
  if not d.atPanel and roomCam("oliver", d) == c then  -- до 2-й ночи стоит на сцене неактивным
    if not d.on or d.pos == 0 then
      placeFigure("oliver", 155, 168, 118, d.on and .95 or .78)
    elseif d.pos == 1 then placeFigure("oliver", 220, 155, 85, .85)  -- чуть правее, чтобы не стоял ногой на столе
    elseif d.pos == 2 then placeFigure("oliver", 200, 120, 70, .8)  -- по центру левого коридора (К3)
    else
      -- стоит на полу перед щитом (ногами ниже основания щита), а не на самом щите
      lg.setColor(0, 0, 0, .4); lg.ellipse("fill", 168, 168, 30, 4)
      if OLV_BACK then
        -- спиной к камере, лицом к щитку: видно, что он вот-вот вырубит свет
        local bw, bh = OLV_BACK:getDimensions()
        local sc = 112 / bh
        lg.setColor(.88, .88, .88, 1)
        lg.draw(OLV_BACK, 168 + sin(clock * 1.5) * 1, 168, 0, sc, sc, bw / 2, bh)
      else
        placeFigure("oliver", 185, 168, 112, .9)
      end
      lg.setColor(.7, .9, 1, .8)
      for _ = 1, 3 do lg.rectangle("fill", rnd(104, 200), rnd(50, 110), 2, 2) end
    end
  end
  -- Джек: активен с 4-й ночи, до этого стоит на месте
  if c == 7 then
    if not r.on then placeFigure("jack", 160, 126, 94, .55)
    elseif r.rs == 0 then placeFigure("jack", 160, 126, 94, .75)
    elseif r.rs == 1 then placeFigure("jack", 160 + sin(clock * 14) * 1.5, 126, 94, .8, sin(clock * 3) * .06)
    elseif r.rs == 2 then placeFigure("jack", 160, 178, 128, .9, .1) end
  end
  -- забег по западному коридору (К3) к левой двери
  if r.on and c == 3 and r.rs == 3 and r.rp > .1 and r.rp < .9 then
    local k = 1 - r.rp
    placeFigure("jack", 160 - k * 70, 118 + k * 55, 25 + k * 95, .7)
  end
  -- Арчи: активен с 3-й ночи, до этого стоит на месте
  if c == 8 and IMG_SPRITES.archie then
    if not w.on then placeFigure("archie", 50, 150, 70, .5)
    elseif w.ws == 0 then
      if w.wp == 1 then placeFigure("archie", 50, 150, 70, .55) else placeFigure("archie", 140, 150, 76, .55) end
    elseif w.ws == 1 then placeFigure("archie", 190, 160, 100, .65)
    else placeFigure("archie", 255, 172, 150, .9) end
  elseif c == 8 then
    if not w.on then
      figure("archie", 50, 96, .55, .5)  -- стоит на стартовой позиции
    elseif w.ws == 0 then
      if w.wp == 1 then figure("archie", 50, 96, .55, .55) else figure("archie", 140, 96, .6, .55) end
    elseif w.ws == 1 then figure("archie", 190, 98, .8, .65)
    else figure("archie", 272, 64, .7, .9) end
  end
  if c == 1 and not IMG_SPRITES.remy and PNG_NOTE ~= "" then
    T(PNG_NOTE, 4, 168, 312, {1, .85, .3}, 5, nil, "left")
  end
end

function drawCam()
  local c = G.sel
  if G.camLock then
    R(0, 0, W, H, {0, 0, 0})
    static(400, .5)
    T(L("hud_heat_lock"), 0, 70, W, {1, .3, .3}, 10)
    T(L("msg_cam_cool"), 0, 90, W, {.7, .7, .7}, 8)
  else
    lg.setColor(.75, 1, .8)
    lg.draw(BG.cam[c], 0, 0)
    if G.broken[c] then
      R(0, 0, W, H, {0, 0, 0}, .55); static(700, .7)
      T(L("cam_broken"), 0, 66, W, {1, .8, .2}, 9)
    elseif G.camT > 0 then
      static(900, .8); R(0, 0, W, H, {0, 0, 0}, .4)
    else
      drawCamFigures(c)
      static(150, .4)
    end
    R(0, (clock * 40) % (H + 30) - 15, W, 10, {1, 1, 1}, .05)
    vignette(.3)
    if G.zapFx > 0 and c == 6 then
      R(0, 0, W, H, {.7, .85, 1}, .55 * G.zapFx / .45)
      lg.setColor(1, 1, 1, .9)
      for _ = 1, 4 do lg.line(rnd(60, 260), rnd(30, 120), rnd(60, 260), rnd(30, 120)) end
    end
    if G.glitch > 0 then
      spr(G.gk, 160, 90, 3.2, {.8, .8, .8})
      static(500, .8)
    end
  end
  -- интерфейс камер
  if floor(clock * 2) % 2 == 0 then R(8, 33, 5, 5, {.9, 0, 0}) end
  if not G.camLock then
    T(L("cam_title", c, LT("cam_names")[c]), 16, 31, 190, {.85, .85, .85}, 7, nil, "left")
    T("ЗАПИСЬ " .. camStamp(), 200, 31, 114, {.7, .7, .7}, 6, nil, "right")
    -- план здания: комнаты как на карте, в каждой номер камеры и короткое название
    local sc, x0, y0 = camGeomBase()
    R(x0 - 3, y0 - 3, 112 * sc + 6, 96 * sc + 6, {0, 0, 0}, .5)
