      R(x0 + bx * sc, y0 + by * sc, bw * sc, bh * sc, col or {.3, .3, .36}, .9)
    end
    -- коридоры-перемычки между комнатами
    link(10, 22, 8, 6); link(52, 20, 10, 8); link(96, 26, 8, 4)     -- малая сцена, сцена -> зал; призы -> восточный коридор
    link(84, 36, 4, 6)                                               -- зал -> восточный коридор
    link(10, 48, 8, 4); link(10, 76, 8, 4)                          -- зал -> западный коридор -> щиток
    link(96, 70, 8, 6)                                               -- восточный коридор -> мастерская
    link(26, 62, 12, 8); link(74, 62, 14, 8)                        -- повороты коридоров к дверям офиса
    local fx0, fy0, fw0, fh0 = camRect("office")
    R(fx0, fy0, fw0, fh0, {.1, .08, .04}, .9)
    lg.setColor(.7, .6, .3, .9); lg.rectangle("line", fx0 + .5, fy0 + .5, fw0 - 1, fh0 - 1)
    T("ВЫ", fx0, fy0 + fh0 * .35, fw0, {.95, .85, .4}, 8)
    T("ОФИС", fx0, fy0 + fh0 * .35 + 10 * sc, fw0, {.75, .65, .3}, 4.5)
    link(34, 62, 4, 8, {.95, .55, .1}); link(74, 62, 4, 8, {.95, .55, .1})  -- левая и правая двери
    link(74, 82, 4, 8, {.4, .6, .95})                                        -- окно: вид на мастерскую Арчи
    local blink = floor(clock * 4) % 2 == 0
    for id = 1, 8 do
      local bx, by, bw, bh = camRect(id)
      local al = camAlert(id)
      local sel = (G.sel == id)
