      T(CAM_SHORT[id], bx, by + bh * .58, bw, {.75, .75, .75}, 4)
    end
    -- мелкие детали плана: кулисы сцены, столики зала, щиток
    local function dec(bx, by, bw, bh, col, al)
      R(x0 + bx * sc, y0 + by * sc, bw * sc, bh * sc, col, al or .8)
