  btn(110, 160, 100, 18, L("btn_close"))
  if not G.camLock then
    if G.broken[c] then
      btn(2, 150, 106, 22, L("btn_repair"), G.hold == "repair" and {.5, .3, 0} or nil)
      R(2, 174, 106, 3, {.15, .15, .15}); R(2, 174, floor(106 * G.repairP), 3, {.9, .7, .1})
    elseif c == 5 and boxOn() then
      btn(2, 150, 106, 22, L("btn_wind"), G.hold == "wind" and {.2, .5, .2} or nil)
      R(2, 174, 106, 3, {.15, .15, .15})
      R(2, 174, floor(106 * G.box / 100), 3, G.box < 30 and {.9, .1, .1} or {.3, .8, .3})
    elseif c == 6 then
      if G.zapCd > 0 then
        btn(2, 150, 106, 22, L("btn_zap_cd", floor(G.zapCd) + 1), {.2, .2, .25}, {.6, .6, .6})
      else
        btn(2, 150, 106, 22, L("btn_zap"), {.15, .35, .7})
      end
    end
  end
end

function drawVent()
  R(0, 0, W, H, {.015, .015, .02})
  -- стенки воздуховода в перспективе: потолок, пол, левая и правая стенка
  lg.setColor(.12, .12, .14, 1); lg.polygon("fill", 0, 0, W, 0, 194, 70, 126, 70)
  lg.setColor(.17, .155, .14, 1); lg.polygon("fill", 0, H, W, H, 194, 110, 126, 110)
  lg.setColor(.105, .11, .125, 1); lg.polygon("fill", 0, 0, 0, H, 126, 110, 126, 70)
  lg.setColor(.095, .1, .115, 1); lg.polygon("fill", W, 0, W, H, 194, 110, 194, 70)
  -- кабели вдоль стенок и ржавые подтёки
  lg.setColor(.02, .02, .03, 1)
  lg.line(0, 62, 126, 80); lg.line(0, 72, 126, 84); lg.line(W, 150, 194, 100)
  lg.setColor(.35, .15, .08, .18)
  for i = 0, 5 do lg.line(40 + i * 48, 2 + (i % 2) * 6, 70 + i * 36, 66) end
  R(126, 70, 68, 40, {0, 0, 0})
  -- секции воздуховода: швы, заклёпки, аварийные лампы
  for k = 0, 5 do
    local z = ((k / 6) + G.vpos * 4) % 1
    local m = floor(z * z * 118)
    local sc = 1 + (1 - z) * 1.6
    local y0 = floor(m * .55)
    lg.setColor(.38, .38, .43, .4 * (1 - z * .5))
    lg.rectangle("line", m + .5, y0 + .5, W - 2 * m, H - floor(m * 1.1))
    -- заклёпки по верхнему и нижнему краю
    lg.setColor(.5, .5, .55, .45 * (1 - z * .5))
    for t = 1, 7 do
      local rx = m + (W - 2 * m) * t / 8
      lg.rectangle("fill", rx, y0 + 2, sc, sc); lg.rectangle("fill", rx, H - y0 - 3 - sc, sc, sc)
    end
    -- красная аварийная лампа на потолке через секцию
    if k % 2 == 0 then
      local fl = .55 + .25 * math.sin(clock * 9 + k * 2)
      R(W / 2 - 6 * sc, y0 + 3, 12 * sc, 2 * sc, {1, .18, .12}, fl * (1 - z * .4))
      lg.setColor(1, .18, .12, .05 * (1 - z * .4)); lg.ellipse("fill", W / 2, y0 + 6 * sc, 40 * sc, 10 * sc)
    end
  end
  -- пыль, летящая навстречу
  for i = 1, 14 do
    local z = ((i * .137) + G.vpos * 3 + clock * .05) % 1
    local px = 160 + math.sin(i * 12.9) * 130 * z
    local py = 90 + math.cos(i * 7.3) * 70 * z
    R(px, py, 1 + z, 1 + z, {.8, .78, .7}, .25 * z)
  end
  -- решётки на концах: тёплый свет к офису, красный к щитку
  if G.vpos < .15 then
    local a = 1 - G.vpos / .15
    R(126, 66, 68, 48, {.3, .26, .18}, .6 * a)
    for i = 0, 5 do R(128, 72 + i * 7, 64, 2, {.05, .05, .05}, .8 * a) end
    R(124, 64, 72, 3, {.4, .4, .45}, a); R(124, 113, 72, 3, {.4, .4, .45}, a)
  elseif G.vpos > .85 then
    local a = (G.vpos - .85) / .15
    R(126, 66, 68, 48, {.35, .08, .08}, .6 * a)
    for i = 0, 5 do R(128, 72 + i * 7, 64, 2, {.05, .05, .05}, .8 * a) end
    R(124, 64, 72, 3, {.4, .4, .45}, a); R(124, 113, 72, 3, {.4, .4, .45}, a)
  end
  -- знак: если Оливер ещё у щитка, в конце тоннеля видны его глаза (чем ближе, тем ярче)
  if G.black and G.oliver.atPanel and G.vpos > .5 then
    local a = (G.vpos - .5) / .5 * (.55 + .45 * math.sin(clock * 3))
    R(142, 86, 6, 3, {.85, .25, 1}, a); R(172, 86, 6, 3, {.85, .25, 1}, a)
    lg.setColor(.85, .25, 1, .05 * a); lg.circle("fill", 160, 88, 26)
  end
  vignette(.35)
  R(60, 36, 200, 3, {.3, .3, .3})
  R(60 + floor(200 * G.vpos) - 3, 32, 6, 11, {.9, .8, .2})
  T(L("vent_route_office"), 14, 32, 42, {.7, .7, .7}, 6, nil, "right")
  T(L("vent_route_panel"), 264, 32, 44, {.7, .7, .7}, 6, nil, "left")
  btn(112, 126, 96, 18, L("btn_cams"))
  btn(8, 150, 100, 24, L("btn_vent_l"), G.hold == "vl" and {.3, .3, .35} or nil)
  btn(212, 150, 100, 24, L("btn_vent_r"), G.hold == "vr" and {.3, .3, .35} or nil)
  if G.vpos <= .03 then
    btn(112, 150, 96, 24, L("btn_exit_office"), {.3, .2, .1})
  elseif G.vpos >= .97 and G.black then
    btn(112, 150, 96, 24, L("btn_exit_panel"), {.3, .2, .1})
  end
end

