function hud()
  local hr = floor(G.time / (NIGHT_LEN / 7))
  T(hr == 0 and "12:00" or (hr .. ":00"), W - 80, 4, 74, WHITE, 10, nil, "right")
  T(nightText(), W - 80, 17, 74, {.7, .7, .7}, 7, nil, "right")
  T(L("hud_power", floor(G.power)), 6, 4, 100, WHITE, 7, nil, "left")
  T(L("hud_usage"), 6, 15, 44, WHITE, 6, nil, "left")
  local use = 1 + (G.dL and 1 or 0) + (G.dR and 1 or 0) + (G.lL and 1 or 0)
    + (G.lR and 1 or 0) + (G.lW and 1 or 0) + (G.cam and 1 or 0)
  for i = 1, min(6, use) do
    R(50 + (i - 1) * 7, 16, 5, 7, i > 4 and {.9, .1, .1} or (i > 2 and {.9, .7, .1} or {.3, .8, .3}))
  end
  if boxOn() then
    T("♪", 6, 24, 10, WHITE, 7, nil, "left")
    R(16, 27, 44, 4, {.12, .12, .12})
    local bc = {.4, .8, .4}
    if G.box < 30 then bc = (floor(clock * 4) % 2 == 0) and {1, .2, .2} or {.5, .1, .1} end
    R(16, 27, floor(44 * G.box / 100), 4, bc)
  end
  -- шкала нагрева камер (сверху по центру)
  local hot = G.camHeat
  T(G.camLock and L("hud_heat_lock") or L("hud_heat"), 90, 2, 140, G.camLock and {1, .3, .3} or {.8, .8, .8}, 6)
  R(112, 11, 96, 5, {.12, .12, .12})
  R(112, 11, floor(96 * hot / 100), 5, hot >= 80 and {.95, .1, .1} or (hot >= 50 and {.95, .65, .1} or {.3, .8, .3}))
  if G.black then T(L("hud_blackout"), 0, 20, W, {1, .25, .25}, 8, .6 + .4 * sin(clock * 6)) end
end

function drawAlerts()
  local w, r = G.wat, G.run
  local blink = floor(clock * 5) % 2 == 0
  if w.on and w.ws >= 2 and not G.black then
    if w.ws == 3 then R(0, 0, W, H, {.6, 0, 0}, .1 + .08 * sin(clock * 12)) end
    local sxw = WIN.x + WIN.w / 2 - G.camX
  end
end

function drawWorld()
  if G.cam then drawCam()
  elseif G.mode == "vent" then drawVent()
  elseif G.mode == "panel" then drawPanelRoom()
  elseif G.mode == "pc" then drawPC()
  else drawOffice() end
  lg.setColor(1, 1, 1)
  lg.draw(vig, 0, 0)
end

