      lg.rectangle("line", ar[1] + .5, 64.5, 21, 47)
      T(ar[2], ar[1], 80, 22, WHITE, 14, .8)
    end
  end
  drawAlerts()
  if G.call and not G.mute then
    if G.ringT then
      R(8, 44, 304, 16, {0, 0, 0}, .7)
      T(L("call_incoming"), 12, 48, 296, {.9, .9, .9}, 7, floor(clock * 4) % 2 == 0 and 1 or .35, "left")
    elseif not G.voiceOn then -- при озвучке никаких субтитров: только голос и кнопка «ОТКЛ. ЗВОНОК»
      local list = callList(night)
      R(8, 44, 304, 40, {0, 0, 0}, .7)
      T(list[G.call], 12, 47, 296, {.9, .9, .9}, 7, nil, "left")
    end
    btn(254, 30, 60, 12, L("btn_mute"), nil, nil, 6)
  end
  if G.msgT > 0 and G.msg then
    local bw = (G.cam and G.mode == "office") and 194 or 308
    R(6, 118, bw, 24, {0, 0, 0}, .65)
    T(G.msg, 9, 120, bw - 6, {1, .95, .6}, 7, nil, "left")
  end
  scanlines()
end

menuRow = {"remy", "oliver", "archie", "jack", "melody"}
function drawMenu()
  R(0, 0, W, H, {0, 0, 0})
  -- справа: лицо одного аниматроника, который мерцает и меняется (как в меню FNAF 1–2)
  local seg = floor(clock / 2.4)
  local kind = menuRow[seg % #menuRow + 1]
  local ph = clock - seg * 2.4
  local fh = floor(clock * 24)
  local h = math.abs(sin(fh * 12.9898) * 43758.5453) % 1
  local k = .5
  if ph < .35 and h < .6 then k = 0 end            -- смена кадра: быстрое мерцание
  if h < .07 then k = 0 elseif h > .95 then k = .9 end
  if k > 0 then
    local jx = (h > .95 or ph < .35) and rnd(-2, 2) or 0
    if IMG_SPRITES[kind] then
      local im = SPR[kind]
      local iw, ih = im:getDimensions()
      local ex, ey = (EYE[kind] or {.5, .2})[1], (EYE[kind] or {.5, .2})[2]
      local cH = ih * .55
      local cW = cH
      local x0 = max(0, min(iw - cW, ex * iw - cW / 2))
      local y0 = max(0, ey * ih - cH * .3)
      lg.setColor(k * .95, k * .88, k * .92, 1)
      lg.draw(im, lg.newQuad(x0, y0, cW, cH, iw, ih), 150 + jx, 0, 0, 170 / cW, H / cH)
    else
      spr(kind, 235 + jx, 100, 2.4, {k, k, k})
    end
    -- растворение в темноте слева
    for i = 0, 29 do R(150 + i * 2, 0, 2, H, {0, 0, 0}, 1 - i / 30) end
  end
  -- название и подзаголовок слева
  T("LAST", 12, 8, 180, {.93, .93, .93}, 24, nil, "left")
  T("SMILE", 12, 34, 180, {.93, .93, .93}, 24, nil, "left")
  T(L("menu_sub"), 14, 66, 190, {.55, .55, .55}, 6, nil, "left")
  -- пункты меню в столбик, как во FNAF
  local sel = menuSel
  if sel == 2 and maxNight <= 1 then sel = 1 end
  local blink = floor(clock * 2.5) % 2 == 0
  local function item(y, label, n) T(label, 22, y, 180, {.95, .95, .95}, n or 11, nil, "left") end
  local ML = menuLayout()
  item(ML.new, L("menu_new"))
  if MENU_CONF and clock - MENU_CONF < 4 then T("НАЖМИ ЕЩЁ РАЗ — ПРОГРЕСС СБРОСИТСЯ", 22, ML.new + 13, 200, {1, .4, .4}, 5, nil, "left") end
  if maxNight > 1 then
    item(ML.cont, L("menu_continue_short"))
    T(L("night_n", maxNight), 22, ML.cont + 14, 180, {.7, .7, .7}, 7, nil, "left")
  end
  if customUnlocked then item(ML.cust, "СВОЯ НОЧЬ") end
  item(ML.set, L("menu_settings"))
  item(ML.exit, L("menu_exit"))
  if nightReveal then
    T("<", 10, ML.sel, 20, {.8, .8, .8}, 10, nil, "center")
    T(L("menu_pick", selNight), 34, ML.sel + 1, 134, {.8, .8, .8}, 8, nil, "left")
    T(">", 172, ML.sel, 20, {.8, .8, .8}, 10, nil, "center")
  end
  if blink and (sel ~= 3 or nightReveal) then
    local ay = (sel == 1 and ML.new) or (sel == 2 and ML.cont) or (sel == 4 and ML.set) or (sel == 5 and ML.exit) or (sel == 6 and ML.cust) or ML.sel
    T(">>", 4, ay, 20, {.95, .95, .95}, sel == 3 and 9 or 11, nil, "left")
  end
  -- помехи, бегущая полоса, строки развёртки
  static(450, .3)
  R(0, (clock * 37) % (H + 20) - 10, W, 6, {1, 1, 1}, .04)
  scanlines()
  lg.setColor(1, 1, 1)
  lg.draw(vig, 0, 0)
end

function drawJump()
  R(0, 0, W, H, {0, 0, 0})
  local t = jump.t
  local s = min(6.6, 2.5 + t * 22) + sin(t * 60) * .15
  if floor(t * 30) % 2 == 0 then R(0, 0, W, H, {.25, 0, 0}) end
  local name = jump.kind
  if IMG_SPRITES[name] then
    local im = SPR[name]
    local w, h = im:getDimensions()
    local scale = s * (78 / h) * 2.4
    local oy = (name == "oliver") and h * .28 or (HEADLESS[name] and h * scareEY(name) or h * .18)
    local yOff = (name == "oliver") and 110 or (HEADLESS[name] and 74 or 110)  -- Оливер чуть пониже
    lg.setColor(1, 1, 1)
    lg.draw(im, 160 + rnd(-4, 4), yOff + rnd(-4, 4), 0, scale, scale, scareAX(name, w), oy)
  else
    spr(name, 160 + rnd(-5, 5), 92 + rnd(-5, 5), s)
  end
  static(300, .6)
  if t < .1 then R(0, 0, W, H, {1, 1, 1}, .8) end
end

OVER_LINES = {
  remy = "Он всегда стоял у двери.",
  oliver = "Он выключил свет — и дождался.",
  archie = "Он смотрел в окно всю ночь.",
  jack = "Ты услышал его слишком поздно.",
  melody = "Шкатулка доиграла до конца.",
}

function overLine(kind)
  local o = G and G.oliver
  if kind == "oliver" then
    if o and o.route == "door" and not o.atPanel then return "Он пришёл к правой двери." end
    return "Он выключил свет — и дождался."
  elseif kind == "remy" and G then
    if (G.ventT or 0) > 50 or (G.blackT or 0) > 70 then return "Ты слишком долго прятался." end
    if G.out then return "Свет кончился — и он пришёл." end
  end
  return OVER_LINES[kind] or ""
end

local function drawOver()
  R(0, 0, W, H, {.02, 0, .02})
  static(500, .35)
  if over.t > 1 then
    local t = over.t - 1
    local kind = jump.kind
    local fadeIn = min(1, t / .5)
    -- портрет: крупный план лица, красный, с помехами
    local px, py, pw, ph = 16, 28, 104, 124
    R(px - 3, py - 3, pw + 6, ph + 6, {.4 * fadeIn, .03, .05})
    R(px, py, pw, ph, {.04, .01, .02})
    if IMG_SPRITES[kind] then
      local im = SPR[kind]
      local iw, ih = im:getDimensions()
      local ex, ey = (EYE[kind] or {.5, .2})[1], (EYE[kind] or {.5, .2})[2]
      local cH = ih * .42
      local cW = cH * pw / ph
      local x0 = max(0, min(iw - cW, ex * iw - cW / 2))
      local y0 = max(0, ey * ih - cH * .4)
      lg.setColor(.8 * fadeIn, .28 * fadeIn, .28 * fadeIn, 1)
      lg.draw(im, lg.newQuad(x0, y0, cW, cH, iw, ih), px + ((t < 1.5 and rnd(-1, 1)) or 0), py, 0, pw / cW, ph / cH)
    else
      spr(kind, px + pw / 2, py + ph / 2, 1.6, {.8, .3, .3})
    end
    R(px, py, pw, ph, {.6, 0, 0}, .14)
    for i = 1, 3 do R(px, py + (clock * 50 + i * 40) % ph, pw, 2, {1, 1, 1}, .08) end
    -- заголовок с цветным дрожанием (как на плохой видеокассете)
    local jx = (floor(clock * 14) % 9 == 0) and rnd(-2, 2) or 0
    T("КОНЕЦ ИГРЫ", 128 + jx + 1, 41, 190, {.1, .6, .7}, 22, nil, "left")
    T("КОНЕЦ ИГРЫ", 128 + jx - 1, 39, 190, {.95, .05, .05}, 22, nil, "left")
    T("КОНЕЦ ИГРЫ", 128 + jx, 40, 190, {.85, .05, .05}, 22, nil, "left")
    R(128, 70, 176, 1, {.5, .05, .08})
    if t > .3 then
      local k = min(1, (t - .3) / .4)
      T(L("over_by", animName(kind)), 128, 76, 190, {.85 * k, .85 * k, .85 * k}, 9, nil, "left")
      T(overLine(kind), 128, 92, 190, {.8 * k, .45 * k, .45 * k}, 6.5, nil, "left")
      local tm = (G and G.time) or 0
      local hr = floor(tm / (NIGHT_LEN / 6))
      local when = (hr == 0) and "Ты не дожил до 1:00" or ("Ты продержался до " .. hr .. ":00")
      T(when, 128, 106, 190, {.65 * k, .65 * k, .65 * k}, 6.5, nil, "left")
      T(nightText(), 128, 117, 190, {.5 * k, .5 * k, .5 * k}, 6, nil, "left")
    end
    if over.t > 1.5 then
      btn(128, 134, 88, 20, "ПОВТОРИТЬ", {.25, .05, .06})
      btn(222, 134, 88, 20, "В МЕНЮ")
    end
  end
  vignette(.4)
  scanlines()
end

