---------------------------------------------------------------- LÖVE
function love.load()
  lg.setDefaultFilter("nearest", "nearest")
  lg.setLineStyle("rough")
  math.randomseed(os.time())
  canvas = lg.newCanvas(W, H)
  local id = love.image.newImageData(W, H)
  id:mapPixel(function(x, y)
    local dx, dy = (x / W - .5) * 2, (y / H - .5) * 2
    local d = min(1, math.sqrt(dx * dx * .8 + dy * dy * 1.1))
    return 0, 0, 0, max(0, d - .35) ^ 1.5 * 1.3
  end)
  vig = lg.newImage(id)
  vig:setFilter("linear", "linear")
  for name, def in pairs(SPR_DEF) do SPR[name] = bakeSprite(def) end
  -- внешние PNG: ищем remy/oliver по всему проекту (2 уровня), без учёта регистра
  local function allFiles()
    local acc = {}
    local function walk(dir, depth)
      if depth > 2 then return end
      local ok, items = pcall(love.filesystem.getDirectoryItems, dir)
      if not ok or not items then return end
      for _, f in ipairs(items) do
        local path = (dir == "" and f) or (dir .. "/" .. f)
        local info = love.filesystem.getInfo(path)
        if info and info.type == "directory" then
          walk(path, depth + 1)
        else
          acc[#acc + 1] = path
        end
      end
    end
    walk("", 0)
    return acc
  end
  local function takePng(name, path)
    local ok, img = pcall(lg.newImage, path)
    if ok and img then
      local flt = (name == "archie" or name == "jack" or name == "melody") and "linear" or "nearest"
      img:setFilter(flt, flt)
      SPR[name] = img
      IMG_SPRITES[name] = true
      if HEADLESS[name] then EYE[name] = findEyes(path, name) or EYE[name] end
      return true
    end
    return false, tostring(img)
  end
  local files = allFiles()
  local function findFor(name)
    local exact = name:lower() .. ".png"
    local loose
    for _, path in ipairs(files) do
      local low = path:lower()
      local base = low:match("([^/]+)$") or low
      if base == exact then return path end
      if not loose and base:find(name:lower(), 1, true) and base:sub(-4) == ".png" and not base:find("electrical", 1, true) and not base:find("_back", 1, true) then
        loose = path
      end
    end
    return loose
  end
  local bits = {}
  for _, name in ipairs({"remy", "oliver", "archie", "jack", "melody"}) do
    local path = findFor(name)
    if not path then
      bits[#bits + 1] = name .. ": нет файла"
    else
      local ok, err = takePng(name, path)
      if ok then bits[#bits + 1] = name .. ": " .. path
      else bits[#bits + 1] = name .. " ошибка " .. path .. " " .. tostring(err) end
    end
  end
  if not IMG_SPRITES.remy then
    local pngs = {}
    for _, path in ipairs(files) do
      if path:lower():sub(-4) == ".png" then pngs[#pngs + 1] = path end
    end
    PNG_NOTE = table.concat(bits, " | ")
    if #pngs == 0 then PNG_NOTE = PNG_NOTE .. " | png в игре нет"
    else PNG_NOTE = PNG_NOTE .. " | png: " .. table.concat(pngs, ", ") end
  end
  BG.office = bakeOffice()
  BG.cam[1] = bakeStage()
  BG.cam[2] = bakeDining()
  BG.cam[3] = bakeHall("W")
  BG.cam[4] = bakeHall("E")
  BG.cam[5] = bakePrize()
  BG.cam[6] = bakePanelRoom()
  BG.cam[7] = bakeSmallStage()
  BG.cam[8] = bakeYard()
  lg.setCanvas()
  makeSounds()
  -- звук двери из файла (если лежит рядом с main.lua), иначе остаётся синтезированный
  if love.filesystem.getInfo("fnaf-door-slamming.mp3") then
    local ok, src = pcall(love.audio.newSource, "fnaf-door-slamming.mp3", "static")
    if ok and src then src:setVolume(.9); S.door = src end
  end
  -- звуки Джека из файлов (если лежат рядом с main.lua)
  RUN_FILE = false
  if love.filesystem.getInfo("jack_running.mp3") then
    local ok, src = pcall(love.audio.newSource, "jack_running.mp3", "static")
    if ok and src then src:setLooping(true); src:setVolume(.8); S.run = src; RUN_FILE = true end
  end
  if love.filesystem.getInfo("jack_door_hit.mp3") then
    local ok, src = pcall(love.audio.newSource, "jack_door_hit.mp3", "static")
    if ok and src then src:setVolume(1); S.bump = src end
  end
  -- звук переключения камер
  if love.filesystem.getInfo("camera_switch.mp3") then
    local ok, src = pcall(love.audio.newSource, "camera_switch.mp3", "static")
    if ok and src then src:setVolume(1); S.cam = src end
  end
  -- звук главного меню (фон, по кругу)
  if love.filesystem.getInfo("menu_ambience.mp3") then
    local ok, src = pcall(love.audio.newSource, "menu_ambience.mp3", "stream")
    if ok and src then src:setLooping(true); src:setVolume(.55); S.menuamb = src end
  end
  -- Оливер спиной у щитка (картинка из PNG)
  OLV_BACK = nil
  for _, nm in ipairs({"Oliver_Near_Electrical_Panel.png", "oliver_back.png"}) do
    if love.filesystem.getInfo(nm) then
      local ok, img = pcall(lg.newImage, nm)
      if ok and img then img:setFilter("linear", "linear"); OLV_BACK = img; break end
    end
  end
  -- сигнал появления Реми у двери
  if love.filesystem.getInfo("remy_door_arrival.mp3") then
    local ok, src = pcall(love.audio.newSource, "remy_door_arrival.mp3", "static")
    if ok and src then src:setVolume(1); S.remydoor = src end
  end
  -- сигнал прибытия Оливера к правой двери
  if love.filesystem.getInfo("oliver_right_door.mp3") then
    local ok, src = pcall(love.audio.newSource, "oliver_right_door.mp3", "static")
    if ok and src then src:setVolume(1); S.olivdoor = src end
  end
  -- звук нажатия на кнопку света
  if love.filesystem.getInfo("fnaf-buttons-wont-work.mp3") then
    local ok, src = pcall(love.audio.newSource, "fnaf-buttons-wont-work.mp3", "static")
    if ok and src then src:setVolume(1); S.lightbtn = src end
  end
  -- гудение света у дверей и окна (как во FNAF)
  if love.filesystem.getInfo("fnaf-doors-light-buzzing.mp3") then
    local ok, src = pcall(love.audio.newSource, "fnaf-doors-light-buzzing.mp3", "static")
    if ok and src then src:setLooping(true); src:setVolume(.5); S.buzz = src end
  end
  SCARES = {}
  for _, k in ipairs({"remy", "oliver", "archie", "jack", "melody"}) do
    for _, pth in ipairs({"animatronic trimmers/" .. k .. "_jumpscare.mp3", k .. "_jumpscare.mp3"}) do
      if love.filesystem.getInfo(pth) then
        local ok, src = pcall(love.audio.newSource, pth, "static")
        if ok and src then SCARES[k] = src; break end
      end
    end
  end
  loadVolumes()
  loadCustom()
  customUnlocked = love.filesystem.getInfo("custom_unlock.txt") ~= nil
  loadCustomDone()
  maxNight = tonumber((love.filesystem.read("save.txt"))) or tonumber((love.filesystem.read("save.bak"))) or 1
  maxNight = nearestAvailableNight(maxNight)
  selNight = maxNight
  menuAmbience()
end

function drawPause()
  R(0, 0, W, H, {0, 0, 0}, .6)
  T("ПАУЗА", 0, 40, W, WHITE, 12)
  btn(70, 80, 180, 22, "ПРОДОЛЖИТЬ")
  btn(70, 108, 180, 22, "КНОПКИ КАМЕР: " .. CAM_SIZE_NAMES[camSizeIndex()])
  btn(70, 136, 180, 22, "ВЫЙТИ В МЕНЮ")
end

local function drawGame()
  drawGameBase()
  if G and not G.paused then btn(72, 3, 34, 11, "ПАУЗА", nil, nil, 6) end
  if G and G.paused then TN = 0; drawPause() end
end

function love.keypressed(key)
  if key == "escape" and state == "game" and G then
    if G.paused then resumeGame() else pauseGame() end
  end
end

function love.update(dt)
  dt = min(dt, .05)
  clock = clock + dt
  if shake > 0 then shake = max(0, shake - dt * 3) end
  if state == "game" and not (G and G.paused) then
    updateGame(dt)
  elseif state == "jump" then
    jump.t = jump.t + dt
    if jump.t > 1.6 then state = "over"; over.t = 0 end
  elseif state == "prologue" then
    PRO.t = PRO.t + dt
  elseif state == "gallery" then
    if gallery.scare then
      gallery.t = gallery.t + dt
      if gallery.t > 1.4 then gallery.scare = false; gallery.t = 0 end
    end
  elseif state == "over" then
    over.t = over.t + dt
  elseif state == "archive" then
    ARCHIVE.t = ARCHIVE.t + dt
    if ARCHIVE.phase == "transition" and ARCHIVE.t > 6 then finishArchive() end
  elseif state == "win" then
    winT = winT + dt
    if winT > 2 and not winChime then
      winChime = true
      if love.filesystem.getInfo("fnaf-6-am.mp3") then
        local ok, src = pcall(love.audio.newSource, "fnaf-6-am.mp3", "stream")
        if ok and src then WIN6 = src; src:setVolume(getVol("chime")); src:play() else play("chime", 1) end
      else
        play("chime", 1)
      end
    end
  end
end

function love.draw()
  local w, h = lg.getDimensions()
  scale = min(w / W, h / H)
  ox, oy = (w - W * scale) / 2, (h - H * scale) / 2
  TN = 0
  lg.setCanvas(canvas)
  lg.clear(0, 0, 0, 1)
  if state == "menu" then drawMenu()
  elseif state == "custom" then drawCustom()
  elseif state == "challenges" then drawChallenges()
  elseif state == "gallery" then drawGallery()
  elseif state == "settings" then drawSettings()
  elseif state == "game" then drawGame()
  elseif state == "jump" then drawJump()
  elseif state == "over" then drawOver()
  elseif state == "win" then drawWin()
  elseif state == "prologue" then drawPrologue()
  elseif state == "archive" then drawArchive()
  elseif state == "story" then drawStory() end
  lg.setCanvas()
  lg.setColor(1, 1, 1)
  local sx = shake > 0 and (rnd() - .5) * shake * 20 or 0
  lg.draw(canvas, ox + sx, oy, 0, scale, scale)
  flushText()
end
